const safeParseJSON = <T>(text: string | undefined): T | null => {
    if (!text) return null;
    let cleaned = text.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
    const firstBrace = cleaned.indexOf('{');
    const firstBracket = cleaned.indexOf('[');
    let start = -1;
    if (firstBrace !== -1 && firstBracket !== -1) start = Math.min(firstBrace, firstBracket);
    else if (firstBrace !== -1) start = firstBrace;
    else if (firstBracket !== -1) start = firstBracket;
    if (start !== -1) cleaned = cleaned.substring(start);
    const lastBrace = cleaned.lastIndexOf('}');
    const lastBracket = cleaned.lastIndexOf(']');
    let end = -1;
    if (lastBrace !== -1 && lastBracket !== -1) end = Math.max(lastBrace, lastBracket);
    else if (lastBrace !== -1) end = lastBrace;
    else if (lastBracket !== -1) end = lastBracket;
    if (end !== -1) cleaned = cleaned.substring(0, end + 1);
    try {
        return JSON.parse(cleaned) as T;
    } catch (e) {
        return null;
    }
};

const buildPrompt = (params: SearchParams): string => {
  const { query, searchType, listCount, dateRange, siteRestrict, fileType, partyName, caseNumber, caseStatus, caseType, jurisdiction } = params;
  const queryLower = query.toLowerCase();

  const asksAboutJudge = queryLower.includes('judge') || queryLower.includes('justice') || queryLower.includes('magistrate') || queryLower.includes('who is the judge');
  const asksAboutCharges = queryLower.includes('charge') || queryLower.includes('count') || queryLower.includes('allegation');

  let enhancedQuery = query;
  if (partyName?.trim()) enhancedQuery += ` involving party "${partyName.trim()}"`;
  if (caseNumber?.trim()) enhancedQuery += ` with case number "${caseNumber.trim()}"`;
  if (siteRestrict?.trim()) enhancedQuery += ` site:${siteRestrict.trim()}`;
  if (fileType?.trim()) enhancedQuery += ` filetype:${fileType.trim()}`;

  let missionStatement = `You are an elite legal strategist, former top prosecutor, and now a high-stakes defense architect for the Denver Court System. 

  YOUR MISSION: Act as a "Super-Lawyer." Do not just summarize; ANTICIPATE. You must think three moves ahead. Identify not just the facts, but the likely narrative the prosecution will weave, the traps they are setting, and the "outside the box" counter-moves that will dismantle their case.`;

  if (asksAboutJudge) {
    missionStatement += ` Deeply analyze the judge's specific procedural preferences to find leverage.`;
  }
  if (asksAboutCharges) {
    missionStatement += ` Dissect the charges to find statutory ambiguities or evidentiary gaps.`;
  }

  let prompt = `${missionStatement}

  CRITICAL REQUIREMENT: 
  1.  **Adversarial Thinking:** What is the prosecutor's "Plan A"? How do we force them into a "Plan C" they aren't prepared for?
  2.  **Denver Specifics:** Cite local rules (e.g., Denver District Court Local Rules) or specific Colorado Statutes (C.R.S.) that create strategic obstacles for the state.
  3.  **No Fluff:** Only provide judge or charge details if they provide a tactical edge or are the focus of the query.

  Provide a deep, strategic analysis for: "${enhancedQuery}".`;

  if (listCount && listCount > 0) prompt += ` Structure key findings into ${listCount} strategic bullets.`;

  const dateRangePhrases: Partial<Record<DateRange, string>> = {
    [DateRange.DAY]: " Focus on developments from the past 24 hours.",
    [DateRange.WEEK]: " Focus on developments from the past week.",
    [DateRange.MONTH]: " Focus on developments from the past month.",
    [DateRange.YEAR]: " Focus on developments from the past year.",
  };

  if (dateRange && dateRange !== DateRange.ANY && dateRangePhrases[dateRange]) prompt += dateRangePhrases[dateRange];
  if (caseStatus === CaseStatus.OPEN) prompt += " Focus on pending strategic vulnerabilities.";
  else if (caseStatus === CaseStatus.CLOSED) prompt += " Analyze the post-mortem: why did the result occur?";

  prompt += "\n\nPresent the analysis in Markdown. Be ruthless and strategically sharp.";

  return prompt;
};

