export const searchWebWithGemini = async (params: SearchParams, onUpdate: (partialResult: PartialSearchResult) => void): Promise<SearchResult> => {
  const prompt = buildPrompt(params);
  try {
    const stream = await ai.models.generateContentStream({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        tools: [{googleSearch: {}}],
        thinkingConfig: { thinkingBudget: 32768 },
        safetySettings: [{ category: HarmCategory.HARM_CATEGORY_HARASSMENT, threshold: HarmBlockThreshold.BLOCK_NONE }, { category: HarmCategory.HARM_CATEGORY_HATE_SPEECH, threshold: HarmBlockThreshold.BLOCK_NONE }, { category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT, threshold: HarmBlockThreshold.BLOCK_NONE }, { category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT, threshold: HarmBlockThreshold.BLOCK_NONE }],
      }
    });

    let summary = "";
    let sources: Source[] = [];
    const sourceUris = new Set<string>();

    for await (const chunk of stream) {
      let chunkText = "";
      try { chunkText = chunk.text || ""; } catch (e) {}
      if (chunkText) summary += chunkText;
      const groundingChunks = chunk.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (groundingChunks) {
        const newSources = groundingChunks.map((c: any) => ({ title: c.web?.title || 'Unknown Source', uri: c.web?.uri || '#' })).filter((s: Source) => s.uri !== '#' && !sourceUris.has(s.uri));
        newSources.forEach(s => { sourceUris.add(s.uri); sources.push(s); });
      }
      onUpdate({ summary, sources: [...sources] });
    }

    const queryLower = params.query.toLowerCase();
    const explicitlyAsksAboutJudge = queryLower.includes('judge') || queryLower.includes('justice') || queryLower.includes('magistrate');

    onUpdate({ isSummaryStreaming: false, isFollowUpQuestionsLoading: true, isRelatedQueriesLoading: true, isTimelineLoading: true, isIdentifiedJudgesLoading: explicitlyAsksAboutJudge, isAdversarialLoading: true });

    const [followUpQuestions, relatedQueries, timelineEvents, identifiedJudges, adversarialStrategy] = await Promise.all([
        generateFollowUpQuestions(params.query, summary),
        generateRelatedQueries(params.query),
        extractTimelineEvents(summary),
        explicitlyAsksAboutJudge ? identifyJudges(summary) : Promise.resolve([]),
        generateAdversarialStrategy(params.query, summary)
    ]);

    onUpdate({ followUpQuestions, relatedQueries, timelineEvents, identifiedJudges, adversarialStrategy, isFollowUpQuestionsLoading: false, isRelatedQueriesLoading: false, isTimelineLoading: false, isIdentifiedJudgesLoading: false, isAdversarialLoading: false });

    return { summary: summary.trim(), sources, followUpQuestions, relatedQueries, timelineEvents, identifiedJudges, adversarialStrategy, isSummaryStreaming: false, isFollowUpQuestionsLoading: false, isRelatedQueriesLoading: false, isTimelineLoading: false, isIdentifiedJudgesLoading: false };
  } catch (error) { throw error; }
};

import React, { useState, useEffect, useRef, useLayoutEffect } from 'react';
