import TrashIcon from './icons/TrashIcon';
import { MAX_QUERY_LENGTH, MIN_LIST_COUNT, MAX_LIST_COUNT } from '../constants';
import { getHistory, clearHistory as clearHistoryService } from '../services/historyService';

interface SearchFormProps {
  params: SearchParams;
  setParams: React.Dispatch<React.SetStateAction<SearchParams>>;
  onSearch: () => void;
  isLoading: boolean;
  onClear: () => void;
  onSelectHistory: (params: SearchParams) => void;
  onSave: () => void;
  canSave: boolean;
}

export default function SearchForm({ params, setParams, onSearch, isLoading, onClear, onSelectHistory, onSave, canSave }: SearchFormProps): React.ReactNode {
  const [isAdvancedOpen, setIsAdvancedOpen] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [history, setHistory] = useState<SearchParams[]>([]);
  const historyRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (isHistoryOpen) setHistory(getHistory());
  }, [isHistoryOpen]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (historyRef.current && !historyRef.current.contains(event.target as Node)) setIsHistoryOpen(false);
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useLayoutEffect(() => {
    const textarea = textareaRef.current;
    if (textarea) {
      textarea.style.height = 'auto';
      textarea.style.height = `${textarea.scrollHeight}px`;
    }
  }, [params.query]);

  const handleInputChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setParams(prev => ({ ...prev, query: e.target.value }));
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      if (params.query.trim()) onSearch();
    }
  };

  const handleHistoryItemClick = (item: SearchParams) => {
    onSelectHistory(item);
    setIsHistoryOpen(false);
  };

  const handleClearHistory = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm('Clear all search history?')) {
      clearHistoryService();
      setHistory([]);
    }
  };

  return (
    <form onSubmit={(e) => { e.preventDefault(); onSearch(); }} className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 items-start">
        <div className="md:col-span-3 relative">
            <label htmlFor="search-query" className="block text-base font-bold text-slate-200 mb-2">Search Query</label>
            <div className="flex items-start">
              <textarea
                ref={textareaRef}
                id="search-query"
                value={params.query}
                onChange={handleInputChange}
                onKeyDown={handleKeyDown}
                placeholder='e.g. "Judge Chris decisions" or "Anticipate prosecutor response to motion for discovery"'
                className="block w-full px-4 py-3 bg-slate-700 border border-slate-600 rounded-l-md shadow-sm text-slate-100 placeholder-slate-400 focus:outline-none focus:ring-blue-500 focus:border-blue-500 sm:text-base resize-none overflow-hidden min-h-[50px]"
                required
                disabled={isLoading}
                maxLength={MAX_QUERY_LENGTH}
                autoComplete="off"
              />
              <div ref={historyRef} className="relative">
                <button
                    type="button"
                    onClick={() => setIsHistoryOpen(!isHistoryOpen)}
                    disabled={isLoading}
                    className="h-[50px] px-4 bg-slate-700 border border-l-0 border-slate-600 rounded-r-md text-slate-300 hover:bg-slate-600 transition-colors"
                >
                    <HistoryIcon className="w-5 h-5" />
                </button>
                {isHistoryOpen && (
                  <div className="absolute right-0 mt-2 w-80 bg-slate-800 border border-slate-700 rounded-lg shadow-2xl z-20 overflow-hidden ring-1 ring-slate-700">
                    <div className="p-2 border-b border-slate-700 bg-slate-800/50 flex justify-between items-center">
                        <span className="text-xs font-bold text-slate-400 uppercase tracking-wider">Search History</span>
                        {history.length > 0 && (
                            <button type="button" onClick={handleClearHistory} className="text-[10px] flex items-center gap-1 text-red-400 hover:text-red-300 font-bold uppercase py-1 px-2 rounded hover:bg-red-400/10 transition-colors">
                                <TrashIcon className="w-3 h-3" /> Clear
                            </button>
                        )}
                    </div>
                    {history.length > 0 ? (
                      <ul className="py-1 max-h-64 overflow-y-auto">
                        {history.map((item, index) => (
                          <li key={index}>
                            <button type="button" onClick={() => handleHistoryItemClick(item)} className="w-full text-left px-4 py-3 text-sm text-slate-200 hover:bg-slate-700 border-b border-slate-700/50 last:border-0 transition-colors">
                                <div className="font-medium truncate">{item.query}</div>
                                <div className="text-[10px] text-slate-500 mt-1 uppercase font-bold">{item.jurisdiction || 'All'} • {item.caseType || 'All'}</div>
                            </button>
                          </li>
                        ))}
                      </ul>
                    ) : (
                      <div className="px-4 py-8 text-center text-slate-500 text-sm">No recent history.</div>
                    )}
                  </div>
                )}
              </div>
            </div>
        </div>
        <div className="flex gap-2 h-[50px] md:mt-[32px]">
          <button type="submit" disabled={isLoading || !params.query.trim()} className="flex-grow inline-flex justify-center items-center px-6 py-2 border border-transparent text-base font-bold rounded-md shadow-sm text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:bg-slate-700 disabled:cursor-not-allowed transition-all">
            {isLoading ? <SpinnerIcon className="w-5 h-5" /> : 'Search'}
          </button>
          <button type="button" onClick={onClear} disabled={isLoading} className="px-4 py-2 border border-slate-600 text-sm font-bold rounded-md text-slate-300 hover:bg-slate-700 transition-colors">Clear</button>
        </div>
      </div>

      <div className="flex flex-wrap items-center gap-4">
          <button type="button" onClick={() => setIsAdvancedOpen(!isAdvancedOpen)} className="inline-flex items-center text-sm font-bold text-blue-400 hover:text-blue-300">
            <ChevronDownIcon className={`w-4 h-4 mr-1 transition-transform ${isAdvancedOpen ? 'rotate-180' : ''}`} />
            {isAdvancedOpen ? 'Simple Search' : 'Advanced Strategizer'}
          </button>
      </div>

      {isAdvancedOpen && (
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-6 pt-4 border-t border-slate-700 animate-fadeIn">
            <div>
              <label className="block text-xs font-bold text-slate-400 uppercase mb-2">Jurisdiction</label>
              <select value={params.jurisdiction} onChange={(e) => setParams(p => ({...p, jurisdiction: e.target.value as any}))} className="w-full bg-slate-700 border border-slate-600 text-slate-100 rounded-md px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-blue-500">
                  <option value="all">All Denver/CO</option>
                  <option value="denver_district">Denver District Court</option>
                  <option value="denver_county">Denver County Court</option>
                  <option value="colorado_supreme">CO Supreme Court</option>
              </select>
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-400 uppercase mb-2">Case Type</label>
              <select value={params.caseType} onChange={(e) => setParams(p => ({...p, caseType: e.target.value as any}))} className="w-full bg-slate-700 border border-slate-600 text-slate-100 rounded-md px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-blue-500">
                  <option value="all">All Types</option>
                  <option value="criminal">Criminal</option>
                  <option value="civil">Civil</option>
                  <option value="family">Family</option>
              </select>
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-400 uppercase mb-2">Party / Case #</label>
              <input type="text" value={params.partyName || params.caseNumber || ''} onChange={(e) => setParams(p => ({...p, partyName: e.target.value}))} placeholder="Search specific party..." className="w-full bg-slate-700 border border-slate-600 text-slate-100 rounded-md px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-blue-500" />
            </div>
        </div>
      )}
    </form>
  );
}

