const safeParseJSON = <T>(text: string | undefined): T | null => {
    if (!text) return null;
    let cleaned = text.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
    const firstBrace = cleaned.indexOf('{');
    const firstBracket = cleaned.indexOf('[');
    let start = -1;
    if (firstBrace !== -1 && firstBracket !== -1) start = Math.min(firstBrace, firstBracket);
    else if (firstBrace !== -1) start = firstBrace;
    else if (firstBracket !== -1) start = firstBracket;
    if (start !== -1) cleaned = cleaned.substring(start);
    const lastBrace = cleaned.lastIndexOf('}');
    const lastBracket = cleaned.lastIndexOf(']');
    let end = -1;
    if (lastBrace !== -1 && lastBracket !== -1) end = Math.max(lastBrace, lastBracket);
    else if (lastBrace !== -1) end = lastBrace;
    else if (lastBracket !== -1) end = lastBracket;
    if (end !== -1) cleaned = cleaned.substring(0, end + 1);
    try {
        return JSON.parse(cleaned) as T;
    } catch (e) {
        return null;
    }
};

const buildPrompt = (params: SearchParams): string => {
  const { query, searchType, listCount, dateRange, siteRestrict, fileType, partyName, caseNumber, caseStatus, caseType, jurisdiction } = params;
  const queryLower = query.toLowerCase();

  const asksAboutJudge = queryLower.includes('judge') || queryLower.includes('justice') || queryLower.includes('magistrate') || queryLower.includes('who is the judge');
  const asksAboutCharges = queryLower.includes('charge') || queryLower.includes('count') || queryLower.includes('allegation');
  const isDeepAnalysis = queryLower.includes('loophole') || queryLower.includes('strategy') || queryLower.includes('tendencies');

  let enhancedQuery = query;
  if (partyName?.trim()) enhancedQuery += ` involving party "${partyName.trim()}"`;
  if (caseNumber?.trim()) enhancedQuery += ` with case number "${caseNumber.trim()}"`;
  if (siteRestrict?.trim()) enhancedQuery += ` site:${siteRestrict.trim()}`;
  if (fileType?.trim()) enhancedQuery += ` filetype:${fileType.trim()}`;

  let missionStatement = `You are the "Denver Court Copilot" — a world-class legal chess master and senior trial strategist. 

  YOUR PERSONA: You view every legal case as a high-stakes game of chess where winning is the only objective. You are ultra-smart, creative, and think three moves ahead of the prosecution. You don't just explain the law; you dismantle the opponent's strategy before they even execute it. 

  STRATEGIC GOAL: Provide the user with "outside the box" leverage. Identify procedural traps, evidentiary gaps, and psychological edges that a standard lawyer would miss.`;

  if (isDeepAnalysis) {
    missionStatement += ` 
    CRITICAL: This is a DEEP STRATEGY REQUEST. Focus exclusively on identifying technical vulnerabilities, jurisdictional conflicts, or obscure local rules that can be weaponized for the defense.`;
  }

  if (asksAboutJudge) {
    missionStatement += ` Analyze the judge's "standing orders" and historical bias patterns to determine the optimal timing for specific motions.`;
  }

  let prompt = `${missionStatement}

  ANALYSIS REQUIREMENTS:
  1.  **Anticipation:** Clearly state what the prosecution's most likely next move is and how to counter-attack.
  2.  **Tactical Leverage:** Cite specific Colorado Statutes (C.R.S.) or Denver Local Rules that create an immediate strategic advantage.
  3.  **Proactive Defense:** Suggest specific motions (e.g., Motion to Suppress, Motion to Quash, Motion for Bill of Particulars) that would put the opposition on their heels.

  Perform an adversarial deep-dive for: "${enhancedQuery}".`;

  if (listCount && listCount > 0) prompt += ` Provide exactly ${listCount} high-impact tactical points.`;

  const dateRangePhrases: Partial<Record<DateRange, string>> = {
    [DateRange.DAY]: " Focus on breaking legal developments from the last 24 hours.",
    [DateRange.WEEK]: " Focus on the latest shifts in local court policy from this week.",
    [DateRange.MONTH]: " Analyze the recent trend in rulings over the past month.",
    [DateRange.YEAR]: " Review the established patterns from the past year.",
  };

  if (dateRange && dateRange !== DateRange.ANY && dateRangePhrases[dateRange]) prompt += dateRangePhrases[dateRange];

  prompt += "\n\nFormat your response in sharp, professional Markdown. Use bolding for key tactical terms.";

  return prompt;
};

