                }
            },
        });
        return safeParseJSON<any>(response.text) as CrossReferenceResult;
    } catch { throw new Error("Cross-examination failed."); }
};

export const generateNarrativeMap = async (fileBase64: string, fileMime: string, fileName: string): Promise<NarrativeMapResult> => {
