import React, { useCallback, useState, useEffect, useRef } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { type SearchResult, type SearchParams, type AdversarialStrategy } from '../types';
import LinkIcon from './icons/LinkIcon';
import CopyButton from './CopyButton';
import FollowUpQuestions from './FollowUpQuestions';
import DownloadIcon from './icons/DownloadIcon';
import BookmarkIcon from './icons/BookmarkIcon';
import BookmarkFilledIcon from './icons/BookmarkFilledIcon';
import CheckIcon from './icons/CheckIcon';
import ClipboardIcon from './icons/ClipboardIcon';
import RelatedQueries from './RelatedQueries';
import GlobeIcon from './icons/GlobeIcon';
import PdfIcon from './icons/PdfIcon';
import IntelligentAnalysis from './IntelligentAnalysis';
import TimelineChart from './TimelineChart';
import IdentifiedJudges from './IdentifiedJudges';
import SpinnerIcon from './icons/SpinnerIcon';
import VolumeUpIcon from './icons/VolumeUpIcon';
import StopIcon from './icons/StopIcon';
import JudgePredictionWidget from './JudgePredictionWidget';
import AdversarialStrategyWidget from './AdversarialStrategyWidget';
import { generateSpeech } from '../services/geminiService';

interface ResultsDisplayProps {
  output: SearchResult | null;
  searchParams: SearchParams | null;
  isLoading: boolean;
  onQuestionClick: (question: string) => void;
  onAnalysisClick: (analysisPrompt: string) => void;
  onSave: (params: SearchParams, result: SearchResult) => void;
  onRemoveSave: (params: SearchParams) => void;
  isSaved: boolean;
  onJudgeClick: (judgeName: string) => void;
}

const SummarySkeleton = () => (
    <div className="space-y-4">
        <div className="skeleton-item h-4 w-full"></div>
        <div className="skeleton-item h-4 w-11/12"></div>
        <div className="skeleton-item h-4 w-full"></div>
        <div className="skeleton-item h-4 w-5/6"></div>
    </div>
);

export default function ResultsDisplay({ output, searchParams, isLoading, onQuestionClick, onAnalysisClick, onSave, onRemoveSave, isSaved, onJudgeClick }: ResultsDisplayProps): React.ReactNode {
  const [copiedAll, setCopiedAll] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isAudioLoading, setIsAudioLoading] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  useEffect(() => {
    if (isLoading) stopAudio();
  }, [isLoading]);

  const stopAudio = () => {
      if (audioSourceRef.current) {
          try { audioSourceRef.current.stop(); } catch(e) {}
          audioSourceRef.current = null;
      }
      setIsPlaying(false);
  };

  const handleToggleAudio = async () => {
      if (isPlaying) { stopAudio(); return; }
      if (!output?.summary) return;
      setIsAudioLoading(true);
      try {
          const base64Audio = await generateSpeech(output.summary);
          if (!audioContextRef.current) audioContextRef.current = new AudioContext({ sampleRate: 24000 });
          if (audioContextRef.current.state === 'suspended') await audioContextRef.current.resume();
          const binaryString = atob(base64Audio);
          const len = binaryString.length;
          const bytes = new Uint8Array(len);
          for (let i = 0; i < len; i++) bytes[i] = binaryString.charCodeAt(i);
          const dataInt16 = new Int16Array(bytes.buffer);
          const frameCount = dataInt16.length;
          const buffer = audioContextRef.current.createBuffer(1, frameCount, 24000);
          const channelData = buffer.getChannelData(0);
          for (let i = 0; i < frameCount; i++) channelData[i] = dataInt16[i] / 32768.0;
          const source = audioContextRef.current.createBufferSource();
          source.buffer = buffer;
          source.connect(audioContextRef.current.destination);
          source.onended = () => { setIsPlaying(false); audioSourceRef.current = null; };
          source.start();
          audioSourceRef.current = source;
          setIsPlaying(true);
      } catch (error) { console.error("Audio error:", error); } finally { setIsAudioLoading(false); }
  };

  if (!output && !isLoading) return null;

  return (
    <div className="bg-slate-800 p-6 rounded-lg shadow-md border border-slate-700 min-h-[24rem]">
      <div className="flex justify-between items-center mb-4">
        <h3 className="text-xl font-black text-slate-100 uppercase tracking-widest text-sm flex items-center gap-2">
            <span className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></span>
            Strategic Dossier
        </h3>
        {output && searchParams && (
            <div className="flex items-center gap-2">
                <button onClick={handleToggleAudio} disabled={isAudioLoading} className="p-2 rounded-full text-slate-300 hover:bg-slate-700 transition-colors" title="AI Voice Analysis">
                    {isAudioLoading ? <SpinnerIcon className="w-5 h-5 text-blue-400" /> : isPlaying ? <StopIcon className="w-5 h-5 text-red-400" /> : <VolumeUpIcon className="w-5 h-5" />}
                </button>
                <button onClick={() => isSaved ? onRemoveSave(searchParams) : onSave(searchParams, output)} className="p-2 rounded-full text-slate-300 hover:bg-slate-700 transition-colors" title="Bookmark Report">
                    {isSaved ? <BookmarkFilledIcon className="w-5 h-5 text-yellow-400" /> : <BookmarkIcon className="w-5 h-5" />}
                </button>
            </div>
        )}
      </div>

      <div className="bg-slate-900/70 border border-slate-700 rounded-md p-6 min-h-[20rem] space-y-10">
        {isLoading && !output?.summary ? <SummarySkeleton /> : output ? (
          <>
            <div className="text-slate-200 text-lg leading-relaxed prose prose-invert max-w-none">
                <ReactMarkdown remarkPlugins={[remarkGfm]}>{output.summary}</ReactMarkdown>
                {output.isSummaryStreaming && <span className="inline-block w-1.5 h-5 bg-blue-500 ml-1 animate-pulse align-middle"></span>}
            </div>

            {/* Adversarial Analysis - Priority Strategic View */}
            <AdversarialStrategyWidget 
                strategy={output.adversarialStrategy} 
                isLoading={output.isAdversarialLoading} 
            />

            <div className="space-y-10">
                {output.identifiedJudges && output.identifiedJudges.length > 0 && (
                    <IdentifiedJudges judges={output.identifiedJudges} isLoading={output.isIdentifiedJudgesLoading} onJudgeClick={onJudgeClick} />
                )}

                {output.timelineEvents && output.timelineEvents.length > 0 && (
                    <TimelineChart events={output.timelineEvents} isLoading={output.isTimelineLoading} />
                )}

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    {output.followUpQuestions && <FollowUpQuestions questions={output.followUpQuestions} onQuestionClick={onQuestionClick} />}
                    {output.relatedQueries && <RelatedQueries queries={output.relatedQueries} onQueryClick={onQuestionClick} />}
                </div>

                <IntelligentAnalysis onAnalysisClick={onAnalysisClick} />

                {output.sources.length > 0 && (
                    <div className="pt-6 border-t border-slate-700">
                        <h4 className="text-[10px] font-black text-slate-500 uppercase mb-4 tracking-[0.3em]">Evidentiary Intelligence Sources</h4>
                        <ul className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                            {output.sources.map((s, i) => (
                                <li key={i} className="flex items-center gap-3 p-2.5 rounded bg-slate-800/30 hover:bg-slate-800 border border-slate-700/50 hover:border-slate-500 transition-all">
                                    <GlobeIcon className="w-4 h-4 text-slate-500" />
                                    <a href={s.uri} target="_blank" rel="noopener" className="text-sm font-medium text-blue-400 hover:text-blue-300 truncate">{s.title}</a>
                                </li>
                            ))}
                        </ul>
                    </div>
                )}
            </div>
          </>
        ) : null}
      </div>
    </div>
  );
}

