import AdversarialStrategyWidget from './AdversarialStrategyWidget';
import { generateSpeech } from '../services/geminiService';

interface ResultsDisplayProps {
  output: SearchResult | null;
  searchParams: SearchParams | null;
  isLoading: boolean;
  onQuestionClick: (question: string) => void;
  onAnalysisClick: (analysisPrompt: string) => void;
  onSave: (params: SearchParams, result: SearchResult) => void;
  onRemoveSave: (params: SearchParams) => void;
  isSaved: boolean;
  onJudgeClick: (judgeName: string) => void;
}

const SummarySkeleton = () => (
    <div className="space-y-6">
        <div className="skeleton-item h-4 w-full opacity-50"></div>
        <div className="skeleton-item h-4 w-11/12 opacity-40"></div>
        <div className="skeleton-item h-4 w-full opacity-30"></div>
        <div className="skeleton-item h-4 w-5/6 opacity-20"></div>
    </div>
);

export default function ResultsDisplay({ output, searchParams, isLoading, onQuestionClick, onAnalysisClick, onSave, onRemoveSave, isSaved, onJudgeClick }: ResultsDisplayProps): React.ReactNode {
  const [isPlaying, setIsPlaying] = useState(false);
  const [isAudioLoading, setIsAudioLoading] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  useEffect(() => {
    if (isLoading) stopAudio();
  }, [isLoading]);

  const stopAudio = () => {
      if (audioSourceRef.current) {
          try { audioSourceRef.current.stop(); } catch(e) {}
          audioSourceRef.current = null;
      }
      setIsPlaying(false);
  };

  const handleToggleAudio = async () => {
      if (isPlaying) { stopAudio(); return; }
      if (!output?.summary) return;
      setIsAudioLoading(true);
      try {
          const base64Audio = await generateSpeech(output.summary);
          if (!audioContextRef.current) audioContextRef.current = new AudioContext({ sampleRate: 24000 });
          if (audioContextRef.current.state === 'suspended') await audioContextRef.current.resume();
          const binaryString = atob(base64Audio);
          const len = binaryString.length;
          const bytes = new Uint8Array(len);
          for (let i = 0; i < len; i++) bytes[i] = binaryString.charCodeAt(i);
          const dataInt16 = new Int16Array(bytes.buffer);
          const frameCount = dataInt16.length;
          const buffer = audioContextRef.current.createBuffer(1, frameCount, 24000);
          const channelData = buffer.getChannelData(0);
          for (let i = 0; i < frameCount; i++) channelData[i] = dataInt16[i] / 32768.0;
          const source = audioContextRef.current.createBufferSource();
          source.buffer = buffer;
          source.connect(audioContextRef.current.destination);
          source.onended = () => { setIsPlaying(false); audioSourceRef.current = null; };
          source.start();
          audioSourceRef.current = source;
          setIsPlaying(true);
      } catch (error) { console.error("Audio error:", error); } finally { setIsAudioLoading(false); }
  };

  if (!output && !isLoading) return null;

  return (
    <div className="bg-[#121212] p-1 rounded-none shadow-[0_30px_60px_rgba(0,0,0,0.5)] border-l border-[#6e501a] relative overflow-hidden group">
      <div className="absolute inset-0 pointer-events-none opacity-[0.03]" style={{ backgroundImage: 'radial-gradient(#ffffff 1px, transparent 1px)', backgroundSize: '30px 30px' }}></div>
      <div className="absolute top-0 left-0 right-0 h-[2px] bg-gradient-to-r from-[#6e501a] via-[#e2c07d] to-[#6e501a]"></div>

      <div className="p-8 sm:p-12 space-y-12 relative z-10">
          <div className="flex justify-between items-center pb-6 border-b border-[#6e501a]/20">
            <h3 className="text-xl font-black text-[#efefef] uppercase tracking-[0.2em] italic flex items-center gap-3">
                <span className="w-2 h-2 bg-[#b5892f] rounded-full animate-pulse shadow-[0_0_10px_#b5892f]"></span>
                Intelligence Dossier
            </h3>
            {output && searchParams && (
                <div className="flex items-center gap-3">
                    <button onClick={handleToggleAudio} disabled={isAudioLoading} className="p-2.5 rounded-full text-[#b5892f] hover:bg-[#b5892f]/10 border border-[#6e501a]/30 transition-all" title="Audio Intel">
                        {isAudioLoading ? <SpinnerIcon className="w-5 h-5 text-[#e2c07d]" /> : isPlaying ? <StopIcon className="w-5 h-5 text-red-500" /> : <VolumeUpIcon className="w-5 h-5" />}
                    </button>
                    <button onClick={() => isSaved ? onRemoveSave(searchParams) : onSave(searchParams, output)} className="p-2.5 rounded-full text-[#b5892f] hover:bg-[#b5892f]/10 border border-[#6e501a]/30 transition-all" title="Save to Vault">
                        {isSaved ? <BookmarkFilledIcon className="w-5 h-5 text-[#e2c07d]" /> : <BookmarkIcon className="w-5 h-5" />}
                    </button>
                </div>
            )}
          </div>

          <div className="space-y-12">
            {isLoading && !output?.summary ? <SummarySkeleton /> : output ? (
              <>
                <div className="text-[#a0a0a0] text-lg leading-relaxed prose prose-invert max-w-none font-light prose-headings:text-[#e2c07d] prose-strong:text-white prose-strong:font-black">
                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{output.summary}</ReactMarkdown>
                    {output.isSummaryStreaming && <span className="inline-block w-2 h-6 bg-[#b5892f] ml-2 animate-pulse align-middle"></span>}
                </div>

                {/* Adversarial War Room */}
                <AdversarialStrategyWidget 
                    strategy={output.adversarialStrategy} 
                    isLoading={output.isAdversarialLoading} 
                />

                <div className="space-y-12">
                    {output.identifiedJudges && output.identifiedJudges.length > 0 && (
                        <IdentifiedJudges judges={output.identifiedJudges} isLoading={output.isIdentifiedJudgesLoading} onJudgeClick={onJudgeClick} />
                    )}

                    {output.timelineEvents && output.timelineEvents.length > 0 && (
                        <TimelineChart events={output.timelineEvents} isLoading={output.isTimelineLoading} />
                    )}

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                        {output.followUpQuestions && <FollowUpQuestions questions={output.followUpQuestions} onQuestionClick={onQuestionClick} />}
                        {output.relatedQueries && <RelatedQueries queries={output.relatedQueries} onQueryClick={onQuestionClick} />}
                    </div>

                    <IntelligentAnalysis onAnalysisClick={onAnalysisClick} />

                    {output.sources.length > 0 && (
                        <div className="pt-10 border-t border-[#6e501a]/30">
                            <h4 className="text-[10px] font-black text-[#6e501a] uppercase mb-6 tracking-[0.5em]">Evidentiary Sources (Authenticated)</h4>
                            <ul className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                                {output.sources.map((s, i) => (
                                    <li key={i} className="flex items-center gap-4 p-4 rounded-none bg-[#0d0d0d] hover:bg-[#1a1a1a] border border-[#6e501a]/20 hover:border-[#b5892f]/50 transition-all group/src">
                                        <GlobeIcon className="w-4 h-4 text-[#6e501a] group-hover/src:text-[#b5892f]" />
                                        <a href={s.uri} target="_blank" rel="noopener" className="text-xs font-mono font-bold text-[#b5892f] hover:text-[#e2c07d] truncate uppercase tracking-widest">{s.title}</a>
                                    </li>
                                ))}
                            </ul>
                        </div>
                    )}
                </div>
              </>
            ) : null}
          </div>
      </div>
    </div>
  );
}

