import React, { useState } from 'react';
import { type Bookmark } from '../types';
import ChevronDownIcon from './icons/ChevronDownIcon';
import EyeIcon from './icons/EyeIcon';
import TrashIcon from './icons/TrashIcon';
import BookmarkFilledIcon from './icons/BookmarkFilledIcon';
import DocumentIcon from './icons/DocumentIcon';
import ScaleIcon from './icons/ScaleIcon';
import GavelIcon from './icons/GavelIcon';

interface BookmarksProps {
  bookmarks: Bookmark[];
  onView: (bookmark: Bookmark) => void;
  onDelete: (key: string) => void;
}

export default function Bookmarks({ bookmarks, onView, onDelete }: BookmarksProps): React.ReactNode {
  const [isOpen, setIsOpen] = useState(false);

  if (bookmarks.length === 0) {
    return null;
  }

  const getIcon = (type: Bookmark['type']) => {
      switch (type) {
          case 'search': return <GavelIcon className="w-5 h-5 text-[#b5892f]" />;
          case 'document_analysis': return <DocumentIcon className="w-5 h-5 text-[#b5892f]" />;
          case 'cross_reference': return <ScaleIcon className="w-5 h-5 text-[#b5892f]" />;
          default: return <BookmarkFilledIcon className="w-5 h-5 text-[#6e501a]" />;
      }
  };

  const getTitle = (bookmark: Bookmark) => {
      switch (bookmark.type) {
          case 'search': return bookmark.params.query;
          case 'document_analysis': return `Analysis: ${bookmark.result.fileName}`;
          case 'cross_reference': return `Cross-Ref: ${bookmark.result.fileAName} vs ${bookmark.result.fileBName}`;
          default: return 'Unknown Entry';
      }
  };

  return (
    <div className="case-card-base p-6 sm:p-8 rounded-none border-l border-[#6e501a] bg-[#121212]">
      <div className="grain-overlay"></div>
      <button
        type="button"
        onClick={() => setIsOpen(!isOpen)}
        className="flex items-center justify-between w-full text-left focus:outline-none group"
        aria-expanded={isOpen}
      >
        <div className="flex items-center gap-4">
            <div className="p-2 bg-[#050505] border border-[#6e501a]/40 rounded-sm">
                <BookmarkFilledIcon className="w-5 h-5 text-[#b5892f] group-hover:scale-110 transition-transform" />
            </div>
            <div>
                <h3 className="text-sm font-black text-[#efefef] uppercase tracking-[0.2em]">Stored Dossiers ({bookmarks.length})</h3>
                <p className="text-[9px] text-[#6e501a] font-mono uppercase tracking-widest mt-1">Encrypted Vault Storage</p>
            </div>
        </div>
        <ChevronDownIcon className={`w-5 h-5 transition-transform duration-500 text-[#b5892f] ${isOpen ? 'rotate-180' : ''}`} />
      </button>

      {isOpen && (
        <div className="mt-8 pt-8 border-t border-[#6e501a]/20 animate-[fadeIn_0.4s_ease-out] space-y-4">
          <ul className="space-y-3">
            {bookmarks.map(bookmark => (
              <li key={bookmark.key} className="p-4 bg-[#050505] border border-[#6e501a]/20 flex justify-between items-center gap-6 group/item hover:border-[#b5892f]/50 transition-all">
                <div className="flex items-center gap-4 flex-grow min-w-0">
                  <div className="flex-shrink-0 p-2 border border-[#6e501a]/10 bg-[#121212]">
                      {getIcon(bookmark.type)}
                  </div>
                  <div className="min-w-0">
                      <p className="text-xs font-bold text-[#e2c07d] truncate uppercase tracking-wider" title={getTitle(bookmark)}>
                        {getTitle(bookmark)}
                      </p>
                      <p className="text-[9px] font-mono text-[#6e501a] mt-1 tracking-widest">
                        {new Date(bookmark.savedAt).toLocaleDateString()} // DOCKET_DATE
                      </p>
                  </div>
                </div>
                <div className="flex items-center gap-3 flex-shrink-0">
                  <button 
                    onClick={() => onView(bookmark)} 
                    className="p-2 text-[#6e501a] hover:text-[#e2c07d] hover:bg-[#b5892f]/5 transition-all"
                    title="Access Intel"
                  >
                    <EyeIcon className="w-5 h-5" />
                  </button>
                  <button 
                    onClick={() => onDelete(bookmark.key)}
                    className="p-2 text-[#6e501a] hover:text-red-500 hover:bg-red-500/5 transition-all"
                    title="Purge Log"
                  >
                     <TrashIcon className="w-5 h-5" />
                  </button>
                </div>
              </li>
            ))}
          </ul>
        </div>
      )}
      <style>{`@keyframes fadeIn { from { opacity: 0; transform: translateY(-10px); } to { opacity: 1; transform: translateY(0); } }`}</style>
    </div>
  );
}

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { DocumentAnalysisResult } from '../types';
import { askDocumentQuestion } from '../services/geminiService';
import SpinnerIcon from './icons/SpinnerIcon';
import DocumentIcon from './icons/DocumentIcon';
import CloseIcon from './icons/CloseIcon';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import GavelIcon from './icons/GavelIcon';
import CalendarIcon from './icons/CalendarIcon';
import UserIcon from './icons/UserIcon';
import NumberIcon from './icons/NumberIcon';
import BrainCircuitIcon from './icons/BrainCircuitIcon';
import BookmarkIcon from './icons/BookmarkIcon';
import BookmarkFilledIcon from './icons/BookmarkFilledIcon';
import QuestionMarkIcon from './icons/QuestionMarkIcon';

interface DocumentAnalysisModalProps {
    onClose: () => void;
    onAnalyze: (base64Content: string, mimeType: string, fileName: string) => Promise<void>;
    result: DocumentAnalysisResult | null;
    isLoading: boolean;
    error: string | null;
    onSave: (result: DocumentAnalysisResult) => void;
    onRemoveSave: (result: DocumentAnalysisResult) => void;
    isSaved: boolean;
}

const MAX_FILE_SIZE_MB = 10;

const ProcessingView: React.FC = () => {
    const [progress, setProgress] = React.useState(0);
    const [messageIndex, setMessageIndex] = React.useState(0);

    const messages = [
        "Decrypting document structure...",
        "Identifying adversarial parties...",
        "Extracting high-leverage arguments...",
        "Cross-referencing judicial patterns...",
        "Finalizing strategic audit..."
    ];

    React.useEffect(() => {
        const timer = setInterval(() => {
            setProgress((oldProgress) => {
                if (oldProgress >= 90) return 90;
                const remaining = 90 - oldProgress;
                const step = Math.max(0.5, remaining * 0.1); 
                return Math.min(oldProgress + step, 90);
            });
        }, 200);

        const msgTimer = setInterval(() => {
             setMessageIndex(prev => (prev + 1) % messages.length);
        }, 2500);

        return () => {
            clearInterval(timer);
            clearInterval(msgTimer);
        };
    }, []);

    return (
        <div className="flex flex-col items-center justify-center py-24 px-6 animate-[fadeIn_0.5s_ease-in-out] bg-[#050505]">
            <div className="relative w-28 h-28 mb-10">
                <div className="absolute inset-0 rounded-full border-2 border-[#6e501a]/30"></div>
                <div className="absolute inset-0 rounded-full border-2 border-transparent border-t-[#b5892f] animate-spin"></div>
                <div className="absolute inset-0 flex items-center justify-center">
                    <BrainCircuitIcon className="w-12 h-12 text-[#b5892f] animate-pulse" />
                </div>
            </div>

            <h3 className="text-2xl font-black text-[#efefef] uppercase tracking-[0.2em] mb-4 italic">Neural Audit Active</h3>

            <div className="h-6 mb-10">
                <p className="text-[#e2c07d] font-mono text-[10px] uppercase tracking-widest text-center">
                    {messages[messageIndex]}
                </p>
            </div>

            <div className="w-full max-w-sm h-px bg-[#6e501a]/30 rounded-full overflow-hidden mb-4">
                <div 
                    className="h-full bg-[#b5892f] transition-all duration-300 ease-out"
                    style={{ width: `${progress}%` }}
                ></div>
            </div>

            <p className="text-[9px] text-[#6e501a] font-black uppercase tracking-[0.3em]">
                Bypassing Procedural Obscurity... {Math.round(progress)}%
            </p>
        </div>
    );
};

const getEntityIcon = (type: string) => {
  switch (type) {
    case 'judge': return <GavelIcon className="w-4 h-4 mr-2 text-[#b5892f]" />;
    case 'party': return <UserIcon className="w-4 h-4 mr-2 text-[#e2c07d]" />;
    case 'date': return <CalendarIcon className="w-4 h-4 mr-2 text-[#6e501a]" />;
    case 'case_number': return <NumberIcon className="w-4 h-4 mr-2 text-[#b5892f]" />;
    default: return <DocumentIcon className="w-4 h-4 mr-2 text-[#6e501a]" />;
  }
}

interface ChatMessage {
    role: 'user' | 'ai';
    content: string;
}

export default function DocumentAnalysisModal({ onClose, onAnalyze, result, isLoading, error, onSave, onRemoveSave, isSaved }: DocumentAnalysisModalProps): React.ReactNode {
    const [selectedFile, setSelectedFile] = useState<File | null>(null);
    const [dragActive, setDragActive] = useState(false);
    const inputRef = useRef<HTMLInputElement>(null);
    const [localError, setLocalError] = useState<string | null>(null);
    const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
    const [questionInput, setQuestionInput] = useState('');
    const [isAsking, setIsAsking] = useState(false);
    const chatEndRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (chatEndRef.current) chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }, [chatHistory, isAsking]);

    const handleFileChange = useCallback((files: FileList | null) => {
        setLocalError(null);
        if (files && files.length > 0) {
            const file = files[0];
            if (file.type !== 'application/pdf') {
                setLocalError('Invalid Mime Type: Use PDF only.');
                setSelectedFile(null);
                return;
            }
            setSelectedFile(file);
        }
    }, []);

    const handleAnalyzeClick = useCallback(async () => {
        if (!selectedFile) return;
        try {
            const base64Content = await new Promise<string>((resolve, reject) => {
                const reader = new FileReader();
                reader.onload = (e) => resolve((e.target?.result as string).split(',')[1]);
                reader.onerror = () => reject(new Error("Read Failure"));
                reader.readAsDataURL(selectedFile);
            });
            await onAnalyze(base64Content, selectedFile.type, selectedFile.name);
        } catch (e) {
             setLocalError("Audit Initialisation Failed.");
        }
    }, [selectedFile, onAnalyze]);

    const handleAskQuestion = async () => {
        if (!questionInput.trim() || !result) return;
        const userQ = questionInput.trim();
        setQuestionInput('');
        setChatHistory(prev => [...prev, { role: 'user', content: userQ }]);
        setIsAsking(true);
        try {
            const answer = await askDocumentQuestion(result, userQ);
            setChatHistory(prev => [...prev, { role: 'ai', content: answer }]);
        } catch (err) {
            setChatHistory(prev => [...prev, { role: 'ai', content: "Neural Link Interrupted. Try again." }]);
        } finally {
            setIsAsking(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-[#050505]/95 backdrop-blur-md flex justify-center items-center z-50 p-4" onClick={(e) => e.target === e.currentTarget && onClose()}>
            <div className="bg-[#121212] border border-[#6e501a] shadow-[0_40px_100px_rgba(0,0,0,1)] max-w-3xl w-full max-h-[90vh] overflow-y-auto relative custom-scrollbar">
                <div className="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-[#6e501a] via-[#b5892f] to-[#6e501a]"></div>

                <div className="flex justify-between items-center p-6 border-b border-[#6e501a]/20">
                    <h2 className="text-xl font-black text-[#efefef] uppercase tracking-[0.2em] italic flex items-center">
                        <DocumentIcon className="w-6 h-6 mr-4 text-[#b5892f]" />
                        Strategic Evidence Audit
                    </h2>
                    <div className="flex items-center gap-4">
                        {result && (
                            <button onClick={() => isSaved ? onRemoveSave(result) : onSave(result)} className="text-[#b5892f] hover:text-[#e2c07d] transition-colors">
                                {isSaved ? <BookmarkFilledIcon className="w-6 h-6" /> : <BookmarkIcon className="w-6 h-6" />}
                            </button>
                        )}
                        <button onClick={onClose} className="text-[#6e501a] hover:text-[#efefef] transition-colors"><CloseIcon className="w-6 h-6" /></button>
                    </div>
                </div>

                <div className="p-8">
                    {!result && !isLoading ? (
                        <div className="space-y-10">
                            <div
                                onDragOver={(e) => {e.preventDefault(); setDragActive(true);}}
                                onDragLeave={() => setDragActive(false)}
                                onDrop={(e) => {e.preventDefault(); setDragActive(false); handleFileChange(e.dataTransfer.files);}}
                                onClick={() => inputRef.current?.click()}
                                className={`flex flex-col items-center justify-center p-12 border border-dashed transition-all cursor-pointer ${
                                    dragActive ? 'border-[#b5892f] bg-[#b5892f]/5 shadow-inner' : 'border-[#6e501a]/30 bg-[#050505] hover:border-[#b5892f]/50'
                                }`}
                            >
                                <input ref={inputRef} type="file" accept="application/pdf" onChange={(e) => handleFileChange(e.target.files)} className="hidden" />
                                <DocumentIcon className="w-14 h-14 text-[#6e501a] mb-6 group-hover:scale-110 transition-transform" />
                                <p className="text-sm font-bold text-[#e2c07d] uppercase tracking-widest text-center">
                                    Inject Source Dossier (PDF)
                                </p>
                                <p className="text-[10px] text-[#6e501a] mt-2 font-mono uppercase">Max Payload: 10MB</p>
                                {selectedFile && <p className="mt-6 text-xs text-white font-black uppercase tracking-widest bg-[#b5892f] px-3 py-1">{selectedFile.name}</p>}
                            </div>
                            <button
                                onClick={handleAnalyzeClick}
                                disabled={!selectedFile || isLoading}
                                className="w-full py-5 bg-[#b5892f] text-[#050505] font-black uppercase italic tracking-tighter text-xl hover:bg-[#e2c07d] transition-all disabled:opacity-30 shadow-xl"
                            >
                                Execute Intelligence Harvest
                            </button>
                        </div>
                    ) : isLoading ? (
                        <ProcessingView />
                    ) : result ? (
                        <div className="space-y-12 animate-[fadeIn_0.5s_ease-out]">
                            <div className="p-8 bg-[#050505] border-l-4 border-[#b5892f] shadow-inner">
                                <h4 className="text-[10px] font-black text-[#b5892f] uppercase tracking-[0.4em] mb-4">Strategic Dossier Summary</h4>
                                <ReactMarkdown remarkPlugins={[remarkGfm]} className="text-lg text-white leading-relaxed font-light prose prose-invert max-w-none prose-strong:text-[#e2c07d]">
                                    {result.strategicSummary}
                                </ReactMarkdown>
                            </div>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                                <div>
