export default function JudgeDetailModal({ judgeName, onClose }: JudgeDetailModalProps): React.ReactNode {
  const [judgeDetails, setJudgeDetails] = useState<JudgeDetail | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    (async () => {
      try {
        const details = await getJudgeDetails(judgeName);
        setJudgeDetails(details);
      } catch (err) { setError(err instanceof Error ? err.message : 'Dossier Access Denied.'); }
      finally { setIsLoading(false); }
    })();
  }, [judgeName]);

  const chartData = useMemo(() => {
    if (!judgeDetails?.rulingPatternsByCaseType) return [];
    return judgeDetails.rulingPatternsByCaseType.map(item => {
        const match = item.percentage?.match(/(\d+(?:\.\d+)?)%/);
        return { label: item.caseType, value: match ? parseFloat(match[1]) : 0, displayValue: item.percentage || 'N/A' };
    }).filter(i => i.value > 0);
  }, [judgeDetails]);

  return (
    <div className="fixed inset-0 bg-[#050505]/95 backdrop-blur-md flex justify-center items-center z-50 p-4" onClick={(e) => e.target === e.currentTarget && onClose()}>
      <div className="bg-[#121212] border border-[#6e501a] shadow-[0_40px_100px_rgba(0,0,0,1)] max-w-2xl w-full max-h-[90vh] overflow-y-auto relative custom-scrollbar">
        <div className="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-[#6e501a] via-[#b5892f] to-[#6e501a]"></div>
        <div className="flex justify-between items-center p-6 border-b border-[#6e501a]/20">
          <h2 className="text-xl font-black text-[#efefef] uppercase tracking-[0.2em] italic flex items-center">
            <GavelIcon className="w-6 h-6 mr-4 text-[#b5892f]" />
            Judicial Dossier: {judgeName}
          </h2>
          <button onClick={onClose} className="text-[#6e501a] hover:text-[#efefef]"><CloseIcon className="w-6 h-6" /></button>
        </div>

        {isLoading ? (
          <div className="p-20 flex flex-col items-center justify-center">
              <SpinnerIcon className="w-12 h-12 text-[#b5892f] mb-6" />
              <div className="text-[10px] font-black text-[#6e501a] uppercase tracking-[0.5em] animate-pulse">Parsing Records...</div>
          </div>
        ) : error ? (
          <div className="p-10 text-red-500 font-bold text-center uppercase tracking-widest">{error}</div>
        ) : judgeDetails ? (
          <div className="p-10 space-y-12 animate-[fadeIn_0.5s_ease-out]">
            <section>
              <h3 className="text-[10px] font-black text-[#b5892f] uppercase tracking-[0.4em] mb-6">Judicial Tendencies</h3>
              <p className="text-lg text-white font-light leading-relaxed prose prose-invert prose-strong:text-[#e2c07d]">{judgeDetails.tendencies}</p>
            </section>

            <section className="bg-[#050505] p-8 border border-[#6e501a]/20">
              <h3 className="text-[10px] font-black text-[#6e501a] uppercase tracking-[0.3em] mb-8">Outcome Probability Chart</h3>
              <div className="space-y-8">
                  {chartData.map((d, i) => <ChartDataPointView key={i} {...d} />)}
              </div>
            </section>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-10">
                <section>
                    <h3 className="text-[10px] font-black text-[#6e501a] uppercase tracking-[0.3em] mb-6">Bench Stats</h3>
                    <ul className="space-y-4">
                        {judgeDetails.statistics.map((s, i) => (
                            <li key={i} className="bg-[#0d0d0d] p-4 border border-[#6e501a]/10 text-xs text-[#a0a0a0]">
                                {s.convictionRate && <div><span className="text-[#6e501a] font-mono uppercase mr-2 text-[9px]">Conviction Rate:</span> <span className="text-[#e2c07d] font-black">{s.convictionRate}</span></div>}
                                {s.averageSentence && <div><span className="text-[#6e501a] font-mono uppercase mr-2 text-[9px]">Avg Sentence:</span> <span className="text-[#e2c07d] font-black">{s.averageSentence}</span></div>}
                            </li>
                        ))}
                    </ul>
                </section>
                <section>
                    <h3 className="text-[10px] font-black text-[#6e501a] uppercase tracking-[0.3em] mb-6">Notable Decisions</h3>
                    <ul className="space-y-4">
                        {judgeDetails.notableCases.map((c, i) => (
                            <li key={i} className="text-xs">
                                <span className="font-black text-[#e2c07d] block uppercase tracking-wider">{c.caseName}</span>
                                <span className="text-[#6e501a] text-[9px] block uppercase mt-1">{c.outcome} ({c.date})</span>
                            </li>
                        ))}
                    </ul>
                </section>
            </div>

            <section>
              <h3 className="text-[10px] font-black text-[#b5892f] uppercase tracking-[0.4em] mb-6">Strategic Counter-Offensive</h3>
              <div className="bg-[#b5892f]/5 p-8 border border-[#b5892f]/20 prose prose-invert max-w-none text-white leading-relaxed font-light prose-strong:text-[#e2c07d] prose-headings:text-[#e2c07d] prose-li:text-slate-300">
                <ReactMarkdown remarkPlugins={[remarkGfm]}>{judgeDetails.strategicInsights}</ReactMarkdown>
