import React, { useState, useCallback, useRef, useEffect } from 'react';
import { DocumentAnalysisResult } from '../types';
import { askDocumentQuestion } from '../services/geminiService';
import SpinnerIcon from './icons/SpinnerIcon';
import DocumentIcon from './icons/DocumentIcon';
import CloseIcon from './icons/CloseIcon';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import GavelIcon from './icons/GavelIcon';
import CalendarIcon from './icons/CalendarIcon';
import UserIcon from './icons/UserIcon';
import NumberIcon from './icons/NumberIcon';
import BrainCircuitIcon from './icons/BrainCircuitIcon';
import BookmarkIcon from './icons/BookmarkIcon';
import BookmarkFilledIcon from './icons/BookmarkFilledIcon';
import QuestionMarkIcon from './icons/QuestionMarkIcon';
// Added missing ScaleIcon import
import ScaleIcon from './icons/ScaleIcon';

interface DocumentAnalysisModalProps {
    onClose: () => void;
    onAnalyze: (base64Content: string, mimeType: string, fileName: string) => Promise<void>;
    result: DocumentAnalysisResult | null;
    isLoading: boolean;
    error: string | null;
    onSave: (result: DocumentAnalysisResult) => void;
    onRemoveSave: (result: DocumentAnalysisResult) => void;
    isSaved: boolean;
}

const MAX_FILE_SIZE_MB = 10;

const ProcessingView: React.FC = () => {
    const [progress, setProgress] = React.useState(0);
    const [messageIndex, setMessageIndex] = React.useState(0);

    const messages = [
        "Decrypting document structure...",
        "Identifying adversarial parties...",
        "Extracting high-leverage arguments...",
        "Cross-referencing judicial patterns...",
        "Finalizing strategic audit..."
    ];

    React.useEffect(() => {
        const timer = setInterval(() => {
            setProgress((oldProgress) => {
                if (oldProgress >= 90) return 90;
                const remaining = 90 - oldProgress;
                const step = Math.max(0.5, remaining * 0.1); 
                return Math.min(oldProgress + step, 90);
            });
        }, 200);

        const msgTimer = setInterval(() => {
             setMessageIndex(prev => (prev + 1) % messages.length);
        }, 2500);

        return () => {
            clearInterval(timer);
            clearInterval(msgTimer);
        };
    }, []);

    return (
        <div className="flex flex-col items-center justify-center py-24 px-6 animate-[fadeIn_0.5s_ease-in-out] bg-[#050505]">
            <div className="relative w-28 h-28 mb-10">
                <div className="absolute inset-0 rounded-full border-2 border-[#6e501a]/30"></div>
                <div className="absolute inset-0 rounded-full border-2 border-transparent border-t-[#b5892f] animate-spin"></div>
                <div className="absolute inset-0 flex items-center justify-center">
                    <BrainCircuitIcon className="w-12 h-12 text-[#b5892f] animate-pulse" />
                </div>
            </div>

            <h3 className="text-2xl font-black text-[#efefef] uppercase tracking-[0.2em] mb-4 italic">Neural Audit Active</h3>

            <div className="h-6 mb-10">
                <p className="text-[#e2c07d] font-mono text-[10px] uppercase tracking-widest text-center">
                    {messages[messageIndex]}
                </p>
            </div>

            <div className="w-full max-w-sm h-px bg-[#6e501a]/30 rounded-full overflow-hidden mb-4">
                <div 
                    className="h-full bg-[#b5892f] transition-all duration-300 ease-out"
                    style={{ width: `${progress}%` }}
                ></div>
            </div>

            <p className="text-[9px] text-[#6e501a] font-black uppercase tracking-[0.3em]">
                Bypassing Procedural Obscurity... {Math.round(progress)}%
            </p>
        </div>
    );
};

const getEntityIcon = (type: string) => {
  switch (type) {
    case 'judge': return <GavelIcon className="w-4 h-4 mr-2 text-[#b5892f]" />;
    case 'party': return <UserIcon className="w-4 h-4 mr-2 text-[#e2c07d]" />;
    case 'date': return <CalendarIcon className="w-4 h-4 mr-2 text-[#6e501a]" />;
    case 'case_number': return <NumberIcon className="w-4 h-4 mr-2 text-[#b5892f]" />;
    default: return <DocumentIcon className="w-4 h-4 mr-2 text-[#6e501a]" />;
  }
}

interface ChatMessage {
    role: 'user' | 'ai';
    content: string;
}

export default function DocumentAnalysisModal({ onClose, onAnalyze, result, isLoading, error, onSave, onRemoveSave, isSaved }: DocumentAnalysisModalProps): React.ReactNode {
    const [selectedFile, setSelectedFile] = useState<File | null>(null);
    const [dragActive, setDragActive] = useState(false);
    const inputRef = useRef<HTMLInputElement>(null);
    const [localError, setLocalError] = useState<string | null>(null);
    const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
    const [questionInput, setQuestionInput] = useState('');
    const [isAsking, setIsAsking] = useState(false);
    const chatEndRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (chatEndRef.current) chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }, [chatHistory, isAsking]);

    const handleFileChange = useCallback((files: FileList | null) => {
        setLocalError(null);
        if (files && files.length > 0) {
            const file = files[0];
            if (file.type !== 'application/pdf') {
                setLocalError('Invalid Mime Type: Use PDF only.');
                setSelectedFile(null);
                return;
            }
            setSelectedFile(file);
        }
    }, []);

    const handleAnalyzeClick = useCallback(async () => {
        if (!selectedFile) return;
        try {
            const base64Content = await new Promise<string>((resolve, reject) => {
                const reader = new FileReader();
                reader.onload = (e) => resolve((e.target?.result as string).split(',')[1]);
                reader.onerror = () => reject(new Error("Read Failure"));
                reader.readAsDataURL(selectedFile);
            });
            await onAnalyze(base64Content, selectedFile.type, selectedFile.name);
        } catch (e) {
             setLocalError("Audit Initialisation Failed.");
        }
    }, [selectedFile, onAnalyze]);

    const handleAskQuestion = async () => {
        if (!questionInput.trim() || !result) return;
        const userQ = questionInput.trim();
        setQuestionInput('');
        setChatHistory(prev => [...prev, { role: 'user', content: userQ }]);
        setIsAsking(true);
        try {
            const answer = await askDocumentQuestion(result, userQ);
            setChatHistory(prev => [...prev, { role: 'ai', content: answer }]);
        } catch (err) {
            setChatHistory(prev => [...prev, { role: 'ai', content: "Neural Link Interrupted. Try again." }]);
        } finally {
            setIsAsking(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-[#050505]/95 backdrop-blur-md flex justify-center items-center z-50 p-4" onClick={(e) => e.target === e.currentTarget && onClose()}>
            <div className="bg-[#121212] border border-[#6e501a] shadow-[0_40px_100px_rgba(0,0,0,1)] max-w-3xl w-full max-h-[90vh] overflow-y-auto relative custom-scrollbar">
                <div className="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-[#6e501a] via-[#b5892f] to-[#6e501a]"></div>

                <div className="flex justify-between items-center p-6 border-b border-[#6e501a]/20">
                    <h2 className="text-xl font-black text-[#efefef] uppercase tracking-[0.2em] italic flex items-center">
                        <DocumentIcon className="w-6 h-6 mr-4 text-[#b5892f]" />
                        Strategic Evidence Audit
                    </h2>
                    <div className="flex items-center gap-4">
                        {result && (
                            <button onClick={() => isSaved ? onRemoveSave(result) : onSave(result)} className="text-[#b5892f] hover:text-[#e2c07d] transition-colors">
                                {isSaved ? <BookmarkFilledIcon className="w-6 h-6" /> : <BookmarkIcon className="w-6 h-6" />}
                            </button>
                        )}
                        <button onClick={onClose} className="text-[#6e501a] hover:text-[#efefef] transition-colors"><CloseIcon className="w-6 h-6" /></button>
                    </div>
                </div>

                <div className="p-8">
                    {!result && !isLoading ? (
                        <div className="space-y-10">
                            <div
                                onDragOver={(e) => {e.preventDefault(); setDragActive(true);}}
                                onDragLeave={() => setDragActive(false)}
                                onDrop={(e) => {e.preventDefault(); setDragActive(false); handleFileChange(e.dataTransfer.files);}}
                                onClick={() => inputRef.current?.click()}
                                className={`flex flex-col items-center justify-center p-12 border border-dashed transition-all cursor-pointer ${
                                    dragActive ? 'border-[#b5892f] bg-[#b5892f]/5 shadow-inner' : 'border-[#6e501a]/30 bg-[#050505] hover:border-[#b5892f]/50'
                                }`}
                            >
                                <input ref={inputRef} type="file" accept="application/pdf" onChange={(e) => handleFileChange(e.target.files)} className="hidden" />
                                <DocumentIcon className="w-14 h-14 text-[#6e501a] mb-6 group-hover:scale-110 transition-transform" />
                                <p className="text-sm font-bold text-[#e2c07d] uppercase tracking-widest text-center">
                                    Inject Source Dossier (PDF)
                                </p>
                                <p className="text-[10px] text-[#6e501a] mt-2 font-mono uppercase">Max Payload: 10MB</p>
                                {selectedFile && <p className="mt-6 text-xs text-white font-black uppercase tracking-widest bg-[#b5892f] px-3 py-1">{selectedFile.name}</p>}
                            </div>
                            <button
                                onClick={handleAnalyzeClick}
                                disabled={!selectedFile || isLoading}
                                className="w-full py-5 bg-[#b5892f] text-[#050505] font-black uppercase italic tracking-tighter text-xl hover:bg-[#e2c07d] transition-all disabled:opacity-30 shadow-xl"
                            >
                                Execute Intelligence Harvest
                            </button>
                        </div>
                    ) : isLoading ? (
                        <ProcessingView />
                    ) : result ? (
                        <div className="space-y-12 animate-[fadeIn_0.5s_ease-out]">
                            <div className="p-8 bg-[#050505] border-l-4 border-[#b5892f] shadow-inner">
                                <h4 className="text-[10px] font-black text-[#b5892f] uppercase tracking-[0.4em] mb-4">Strategic Dossier Summary</h4>
                                <ReactMarkdown remarkPlugins={[remarkGfm]} className="text-lg text-white leading-relaxed font-light prose prose-invert max-w-none prose-strong:text-[#e2c07d]">
                                    {result.strategicSummary}
                                </ReactMarkdown>
                            </div>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                                <div>
                                    <h4 className="text-[10px] font-black text-[#6e501a] uppercase tracking-[0.3em] mb-6 flex items-center gap-3">
                                        <div className="h-px flex-grow bg-[#6e501a]/20"></div> Arguments
                                    </h4>
                                    <ul className="space-y-3">
                                        {result.keyArguments.map((arg, i) => (
                                            <li key={i} className="text-xs text-[#a0a0a0] pl-4 border-l border-[#6e501a] italic">{arg}</li>
                                        ))}
                                    </ul>
                                </div>
                                <div>
                                    <h4 className="text-[10px] font-black text-[#6e501a] uppercase tracking-[0.3em] mb-6 flex items-center gap-3">
                                        <div className="h-px flex-grow bg-[#6e501a]/20"></div> Entities
                                    </h4>
                                    <ul className="space-y-3">
                                        {result.identifiedEntities.map((entity, i) => (
                                            <li key={i} className="flex items-center text-xs font-bold text-[#efefef] bg-[#0d0d0d] p-3 border border-[#6e501a]/10">
                                                {getEntityIcon(entity.type)}
                                                <span className="text-[9px] font-mono uppercase text-[#6e501a] mr-2">{entity.type}:</span> {entity.value}
                                            </li>
                                        ))}
                                    </ul>
                                </div>
                            </div>

                            <div className="bg-[#b5892f]/5 p-8 border border-[#b5892f]/20">
                                <h4 className="text-[10px] font-black text-[#b5892f] uppercase tracking-[0.4em] mb-6">Tactical Counter-Actions</h4>
                                <ul className="space-y-4">
                                    {result.actionableInsights.map((insight, i) => (
                                        <li key={i} className="flex gap-4 text-sm text-[#e2c07d]">
                                            <span className="font-mono text-[#6e501a]">0{i+1}.</span>
                                            <span className="font-bold leading-tight">{insight}</span>
                                        </li>
                                    ))}
                                </ul>
                            </div>

                            <div className="pt-10 border-t border-[#6e501a]/20">
                                <h4 className="text-[10px] font-black text-[#6e501a] uppercase tracking-[0.3em] mb-6 flex items-center gap-3">
                                    <QuestionMarkIcon className="w-4 h-4 text-[#b5892f]" />
                                    Adversarial Link-Up
                                </h4>
                                <div className="space-y-6 mb-8">
                                    {chatHistory.map((msg, i) => (
                                        <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                                            <div className={`max-w-[90%] p-4 text-xs font-bold ${msg.role === 'user' ? 'bg-[#b5892f] text-[#050505]' : 'bg-[#050505] text-[#e2c07d] border border-[#6e501a]/30 shadow-xl'}`}>
                                                {msg.content}
                                            </div>
                                        </div>
                                    ))}
                                    {isAsking && <div className="text-[9px] font-black uppercase text-[#6e501a] animate-pulse">Calculating response...</div>}
                                    <div ref={chatEndRef}></div>
                                </div>
                                <div className="relative">
                                    <textarea
                                        value={questionInput}
                                        onChange={(e) => setQuestionInput(e.target.value)}
                                        onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleAskQuestion())}
                                        placeholder="Query dossier specifics..."
                                        className="w-full bg-[#050505] border border-[#6e501a] p-5 pr-14 text-[#e2c07d] font-mono-legal text-sm outline-none focus:border-[#b5892f] resize-none"
                                        rows={2}
                                    />
                                    <button onClick={handleAskQuestion} disabled={!questionInput.trim() || isAsking} className="absolute right-4 bottom-5 text-[#b5892f] hover:text-[#e2c07d] disabled:opacity-20"><ScaleIcon className="w-6 h-6" /></button>
                                </div>
                            </div>
                        </div>
                    ) : null}
                </div>
            </div>
            <style>{`@keyframes fadeIn { from { opacity: 0; transform: scale(0.98); } to { opacity: 1; transform: scale(1); } }`}</style>
        </div>
    );
}

import React, { useState, useCallback, useEffect } from 'react';
import { SearchType, type SearchParams, DateRange, CaseStatus, type Bookmark, type SearchBookmark, type DocumentBookmark, type CrossRefBookmark, type PartialSearchResult, type SearchResult, type DocumentAnalysisResult, type CrossReferenceResult, type NarrativeMapResult, CaseType, Jurisdiction } from './types';
import { searchWebWithGemini, analyzeDocument, crossReferenceDocuments, generateNarrativeMap } from './services/geminiService';
import { getCachedResult, setCachedResult, clearCache, generateCacheKey } from './services/cacheService';
import { addToHistory, clearHistory } from './services/historyService';
import { getBookmarks, saveBookmark, removeBookmark, isSearchBookmarked, isDocBookmarked, isCrossRefBookmarked, clearBookmarks, generateSearchKey, generateDocKey, generateCrossRefKey } from './services/bookmarkService';
import { MAX_QUERY_LENGTH, MIN_LIST_COUNT, MAX_LIST_COUNT } from './constants';
import Header from './components/Header';
import Banner from './components/Banner';
import SearchForm from './components/SearchForm';
import ResultsDisplay from './components/ResultsDisplay';
import Examples from './components/Examples';
import Bookmarks from './components/Bookmarks';
import JudgeDetailModal from './components/JudgeDetailModal';
import DocumentAnalysisModal from './components/DocumentAnalysisModal';
import CrossReferenceModal from './components/CrossReferenceModal';
import NarrativeMapper from './components/NarrativeMapper';

export default function App(): React.ReactNode {
  const [searchParams, setSearchParams] = useState<SearchParams>({
    query: '',
    searchType: SearchType.SEARCH,
    listCount: undefined,
    dateRange: DateRange.ANY,
    siteRestrict: '',
    fileType: '',
    partyName: '',
    caseNumber: '',
    caseStatus: CaseStatus.ALL,
    caseType: CaseType.ALL,
    jurisdiction: Jurisdiction.ALL,
  });
  const [currentSearchParamsForResults, setCurrentSearchParamsForResults] = useState<SearchParams | null>(null);
  const [output, setOutput] = useState<SearchResult | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);

  const [showJudgeModal, setShowJudgeModal] = useState(false);
  const [selectedJudgeName, setSelectedJudgeName] = useState<string | null>(null);

  const [showDocumentAnalysisModal, setShowDocumentAnalysisModal] = useState(false);
  const [documentAnalysisResult, setDocumentAnalysisResult] = useState<DocumentAnalysisResult | null>(null);
  const [isDocumentAnalysisLoading, setIsDocumentAnalysisLoading] = useState<boolean>(false);
  const [documentAnalysisError, setDocumentAnalysisError] = useState<string | null>(null);

  const [showCrossRefModal, setShowCrossRefModal] = useState(false);
  const [crossRefResult, setCrossRefResult] = useState<CrossReferenceResult | null>(null);
  const [isCrossRefLoading, setIsCrossRefLoading] = useState(false);
  const [crossRefError, setCrossRefError] = useState<string | null>(null);

  const [showNarrativeMapper, setShowNarrativeMapper] = useState(false);

  useEffect(() => {
    setBookmarks(getBookmarks());
  }, []);

  const executeSearch = useCallback(async (params: SearchParams) => {
    const finalParams: SearchParams = { ...params, query: params.query.trim() };

    if (!finalParams.query) {
      setError('Search query cannot be empty.');
      return;
    }
    if (finalParams.query.length > MAX_QUERY_LENGTH) {
      setError(`Search query cannot exceed ${MAX_QUERY_LENGTH} characters.`);
      return;
    }
    const { listCount } = finalParams;
    if (listCount !== undefined && (listCount < MIN_LIST_COUNT || listCount > MAX_LIST_COUNT)) {
      setError(`List count must be between ${MIN_LIST_COUNT} and ${MAX_LIST_COUNT}.`);
      return;
    }

    const cachedResult = getCachedResult(finalParams);
    if (cachedResult) {
      setOutput({
        ...cachedResult,
        isSummaryStreaming: false,
        isFollowUpQuestionsLoading: false,
        isRelatedQueriesLoading: false,
        isTimelineLoading: false,
        isIdentifiedJudgesLoading: false,
      });
      setCurrentSearchParamsForResults(finalParams);
      setError(null);
      window.scrollTo({ top: 0, behavior: 'smooth' });
      return;
    }

    setIsLoading(true);
    setError(null);
    setOutput({
      summary: '',
      sources: [],
      followUpQuestions: [],
      relatedQueries: [],
      timelineEvents: [],
      identifiedJudges: [],
      isSummaryStreaming: true,
      isFollowUpQuestionsLoading: false,
      isRelatedQueriesLoading: false,
      isTimelineLoading: false,
      isIdentifiedJudgesLoading: false,
    });
    setCurrentSearchParamsForResults(finalParams);
    window.scrollTo({ top: 0, behavior: 'smooth' });

    try {
      const onUpdate = (partialResult: PartialSearchResult) => {
        setOutput(prev => {
            const current = prev || {
                summary: '',
                sources: [],
                followUpQuestions: [],
                relatedQueries: [],
                timelineEvents: [],
                identifiedJudges: [],
                isSummaryStreaming: false,
                isFollowUpQuestionsLoading: false,
                isRelatedQueriesLoading: false,
                isTimelineLoading: false,
                isIdentifiedJudgesLoading: false,
            };

            return {
                summary: partialResult.summary ?? current.summary,
                sources: partialResult.sources ?? current.sources,
                followUpQuestions: partialResult.followUpQuestions ?? current.followUpQuestions,
                relatedQueries: partialResult.relatedQueries ?? current.relatedQueries,
                timelineEvents: partialResult.timelineEvents ?? current.timelineEvents,
                identifiedJudges: partialResult.identifiedJudges ?? current.identifiedJudges,
                isSummaryStreaming: partialResult.isSummaryStreaming ?? current.isSummaryStreaming,
                isFollowUpQuestionsLoading: partialResult.isFollowUpQuestionsLoading ?? current.isFollowUpQuestionsLoading,
                isRelatedQueriesLoading: partialResult.isRelatedQueriesLoading ?? current.isRelatedQueriesLoading,
                isTimelineLoading: partialResult.isTimelineLoading ?? current.isTimelineLoading,
                isIdentifiedJudgesLoading: partialResult.isIdentifiedJudgesLoading ?? current.isIdentifiedJudgesLoading,
            };
        });
      };

      const result = await searchWebWithGemini(finalParams, onUpdate);
      setOutput(prev => ({
          ...prev!,
          ...result,
          isSummaryStreaming: false,
          isFollowUpQuestionsLoading: false,
          isRelatedQueriesLoading: false,
          isTimelineLoading: false,
          isIdentifiedJudgesLoading: false,
      }));
      setCachedResult(finalParams, result);
      addToHistory(finalParams);
    } catch (err) {
      console.error(err);
      setError(err instanceof Error ? err.message : 'An unknown error occurred. Please try again.');
      setOutput(null);
      setCurrentSearchParamsForResults(null);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const handleSearch = useCallback(() => {
    executeSearch(searchParams);
  }, [searchParams, executeSearch]);

  const handleFollowUpSearch = useCallback((question: string) => {
    const newParams: SearchParams = {
      query: question,
      searchType: searchParams.searchType,
      listCount: undefined,
      dateRange: DateRange.ANY,
      siteRestrict: '',
      fileType: '',
      partyName: '',
      caseNumber: '',
      caseStatus: CaseStatus.ALL,
      caseType: CaseType.ALL,
      jurisdiction: Jurisdiction.ALL,
    };
    setSearchParams(newParams);
    executeSearch(newParams);
  }, [searchParams.searchType, executeSearch]);

  const handleAnalysisSearch = useCallback((analysisPrompt: string) => {
    if (!currentSearchParamsForResults?.query) return;

    const newQuery = `${analysisPrompt} for "${currentSearchParamsForResults.query}"`;
    const newParams: SearchParams = {
      query: newQuery,
      searchType: SearchType.SEARCH,
      listCount: undefined,
      dateRange: DateRange.ANY,
      siteRestrict: '',
      fileType: '',
      partyName: '',
      caseNumber: '',
      caseStatus: CaseStatus.ALL,
      caseType: CaseType.ALL,
      jurisdiction: Jurisdiction.ALL,
    };
    setSearchParams(newParams);
    executeSearch(newParams);
  }, [currentSearchParamsForResults, executeSearch]);


  const handleClearSearch = useCallback(() => {
    setSearchParams({
      query: '',
      searchType: SearchType.SEARCH,
      listCount: undefined,
      dateRange: DateRange.ANY,
      siteRestrict: '',
      fileType: '',
      partyName: '',
      caseNumber: '',
      caseStatus: CaseStatus.ALL,
      caseType: CaseType.ALL,
      jurisdiction: Jurisdiction.ALL,
    });
    setOutput(null);
    setCurrentSearchParamsForResults(null);
    setError(null);
    setShowJudgeModal(false);
    setSelectedJudgeName(null);
    setDocumentAnalysisResult(null);
    setDocumentAnalysisError(null);
    setShowDocumentAnalysisModal(false);
    setCrossRefResult(null);
    setShowCrossRefModal(false);
  }, []);

  const handleClearLocalData = useCallback(() => {
    if (window.confirm('Wipe all cached intelligence, historical logs, and vault dossiers? This action cannot be undone.')) {
        clearCache();
        clearHistory();
        clearBookmarks();
        setBookmarks([]);
        alert('All operational data purged.');
    }
  }, []);

  const handleExampleSelect = useCallback((example: SearchParams) => {
    setSearchParams({
      query: example.query,
      searchType: example.searchType,
      listCount: example.listCount,
      dateRange: DateRange.ANY,
      siteRestrict: '',
      fileType: '',
      partyName: '',
      caseNumber: '',
      caseStatus: CaseStatus.ALL,
      caseType: CaseType.ALL,
      jurisdiction: Jurisdiction.ALL,
    });
  }, []);

  const handleHistorySelect = useCallback((params: SearchParams) => {
    setSearchParams(params);
    executeSearch(params);
  }, [executeSearch]);

  const handleSaveResult = (params: SearchParams, result: SearchResult) => {
    const key = generateSearchKey(params);
    const bookmark: SearchBookmark = {
        key, type: 'search', params, result, savedAt: Date.now()
    };
    saveBookmark(bookmark);
    setBookmarks(getBookmarks());
  };

  const handleRemoveSave = (params: SearchParams) => {
    const key = generateSearchKey(params);
    removeBookmark(key);
    setBookmarks(getBookmarks());
  };

  const handleSaveDocument = (result: DocumentAnalysisResult) => {
      const key = generateDocKey(result.fileName);
      const bookmark: DocumentBookmark = {
          key, type: 'document_analysis', result, savedAt: Date.now()
      };
      saveBookmark(bookmark);
      setBookmarks(getBookmarks());
  };

  const handleRemoveDocumentSave = (result: DocumentAnalysisResult) => {
      const key = generateDocKey(result.fileName);
      removeBookmark(key);
      setBookmarks(getBookmarks());
  };

  const handleSaveCrossRef = (result: CrossReferenceResult) => {
      const key = generateCrossRefKey(result.fileAName, result.fileBName);
      const bookmark: CrossRefBookmark = {
          key, type: 'cross_reference', result, savedAt: Date.now()
      };
      saveBookmark(bookmark);
      setBookmarks(getBookmarks());
  };

  const handleRemoveCrossRefSave = (result: CrossReferenceResult) => {
      const key = generateCrossRefKey(result.fileAName, result.fileBName);
      removeBookmark(key);
      setBookmarks(getBookmarks());
  };

  const handleDeleteBookmark = (key: string) => {
      removeBookmark(key);
      setBookmarks(getBookmarks());
  };

  const handleViewBookmark = (bookmark: Bookmark) => {
    if (bookmark.type === 'search') {
        setSearchParams(bookmark.params);
        setOutput({
          ...bookmark.result,
          isSummaryStreaming: false,
          isFollowUpQuestionsLoading: false,
          isRelatedQueriesLoading: false,
          isTimelineLoading: false,
          isIdentifiedJudgesLoading: false,
        });
        setCurrentSearchParamsForResults(bookmark.params);
        window.scrollTo({ top: 0, behavior: 'smooth' });
    } else if (bookmark.type === 'document_analysis') {
        setDocumentAnalysisResult(bookmark.result);
        setShowDocumentAnalysisModal(true);
    } else if (bookmark.type === 'cross_reference') {
        setCrossRefResult(bookmark.result);
        setShowCrossRefModal(true);
    }
  };

  const handleSaveCurrentSearch = useCallback(() => {
      if (currentSearchParamsForResults && output) {
          handleSaveResult(currentSearchParamsForResults, output);
      }
  }, [currentSearchParamsForResults, output]);

  const openJudgeModal = useCallback((judgeName: string) => {
    setSelectedJudgeName(judgeName);
    setShowJudgeModal(true);
  }, []);

  const closeJudgeModal = useCallback(() => {
    setShowJudgeModal(false);
    setSelectedJudgeName(null);
  }, []);

  const openDocumentAnalysisModal = useCallback(() => {
    setShowDocumentAnalysisModal(true);
    setDocumentAnalysisResult(null);
    setDocumentAnalysisError(null);
    setIsDocumentAnalysisLoading(false);
  }, []);

  const closeDocumentAnalysisModal = useCallback(() => {
    setShowDocumentAnalysisModal(false);
    setDocumentAnalysisResult(null);
    setDocumentAnalysisError(null);
    setIsDocumentAnalysisLoading(false);
  }, []);

  const handleDocumentAnalysis = useCallback(async (base64Content: string, mimeType: string, fileName: string) => {
    setIsDocumentAnalysisLoading(true);
    setDocumentAnalysisError(null);
    try {
      const result = await analyzeDocument(base64Content, mimeType, fileName);
      setDocumentAnalysisResult(result);
    } catch (err) {
      console.error("Document analysis failed:", err);
      setDocumentAnalysisError(err instanceof Error ? err.message : 'An unknown error occurred during document analysis.');
    } finally {
      setIsDocumentAnalysisLoading(false);
    }
  }, []);

  const openCrossRefModal = useCallback(() => {
    setShowCrossRefModal(true);
    setCrossRefResult(null);
    setCrossRefError(null);
  }, []);

  const closeCrossRefModal = useCallback(() => {
    setShowCrossRefModal(false);
    setCrossRefResult(null);
    setCrossRefError(null);
  }, []);

  const handleCrossReference = useCallback(async (
      fileABase64: string, fileAMime: string, fileAName: string,
      fileBBase64: string, fileBMime: string, fileBName: string
  ) => {
      setIsCrossRefLoading(true);
      setCrossRefError(null);
      try {
          const result = await crossReferenceDocuments(fileABase64, fileAMime, fileAName, fileBBase64, fileBMime, fileBName);
          setCrossRefResult(result);
      } catch (err) {
          console.error("Cross-reference failed:", err);
          setCrossRefError(err instanceof Error ? err.message : 'An unknown error occurred during cross-reference.');
      } finally {
          setIsCrossRefLoading(false);
      }
  }, []);

  const handleNarrativeGeneration = useCallback(async (base64: string, mime: string, name: string): Promise<NarrativeMapResult> => {
      return await generateNarrativeMap(base64, mime, name);
  }, []);

  return (
    <div className="min-h-screen bg-[#050505] text-[#efefef]">
      <main className="max-w-5xl mx-auto p-4 sm:p-8 md:p-12 space-y-16">
        <Banner />

        <Header 
          onAnalyzeDocumentClick={openDocumentAnalysisModal} 
          onCrossReferenceClick={openCrossRefModal} 
          onNarrativeMapperClick={() => setShowNarrativeMapper(true)}
        />

        <div className="space-y-16">
          <div className="case-card-base p-0 rounded-none border-l border-[#6e501a] bg-[#121212] overflow-hidden shadow-2xl">
            <SearchForm
              params={searchParams}
              setParams={setSearchParams}
              onSearch={handleSearch}
              isLoading={isLoading}
              onClear={handleClearSearch}
              onSelectHistory={handleHistorySelect}
              onSave={handleSaveCurrentSearch}
              canSave={!!output && !!currentSearchParamsForResults}
            />
            <div className="px-8 sm:px-12 pb-12">
              <Examples onSelectExample={handleExampleSelect} />
            </div>
          </div>

          <Bookmarks 
            bookmarks={bookmarks}
            onView={handleViewBookmark}
            onDelete={handleDeleteBookmark}
          />

          {error && (
            <div className="bg-red-950/40 border border-red-500/50 text-red-400 p-6 rounded-none font-bold uppercase tracking-widest text-xs animate-pulse" role="alert">
              <span className="text-[#efefef] mr-2">Neural Interface Error:</span>
              {error}
            </div>
          )}

          <ResultsDisplay
            output={output}
            searchParams={currentSearchParamsForResults}
            isLoading={isLoading}
            onQuestionClick={handleFollowUpSearch}
            onAnalysisClick={handleAnalysisSearch}
            onSave={handleSaveResult}
            onRemoveSave={handleRemoveSave}
            isSaved={currentSearchParamsForResults ? isSearchBookmarked(currentSearchParamsForResults) : false}
            onJudgeClick={openJudgeModal}
          />
        </div>
      </main>

      <footer className="max-w-5xl mx-auto px-4 sm:px-12 py-16 text-center border-t border-[#6e501a]/10 space-y-6">
        <p className="text-[10px] font-black uppercase tracking-[0.5em] text-[#6e501a]">
          Tactical Intelligence Node • Synchronized via Gemini Neural Engine
        </p>
        <button
          onClick={handleClearLocalData}
          className="px-6 py-2 bg-transparent border border-[#6e501a] text-[#b5892f] text-[9px] font-black uppercase tracking-[0.2em] hover:bg-[#b5892f] hover:text-[#050505] transition-all"
        >
          Purge Global Dossier Cache
        </button>
      </footer>

      {showJudgeModal && selectedJudgeName && (
        <JudgeDetailModal 
          judgeName={selectedJudgeName} 
          onClose={closeJudgeModal} 
        />
      )}
      {showDocumentAnalysisModal && (
        <DocumentAnalysisModal
          onClose={closeDocumentAnalysisModal}
          onAnalyze={handleDocumentAnalysis}
          result={documentAnalysisResult}
          isLoading={isDocumentAnalysisLoading}
          error={documentAnalysisError}
          onSave={handleSaveDocument}
          onRemoveSave={handleRemoveDocumentSave}
          isSaved={documentAnalysisResult ? isDocBookmarked(documentAnalysisResult.fileName) : false}
        />
      )}
      {showCrossRefModal && (
        <CrossReferenceModal
          onClose={closeCrossRefModal}
          onAnalyze={handleCrossReference}
          result={crossRefResult}
          isLoading={isCrossRefLoading}
          error={crossRefError}
          onSave={handleSaveCrossRef}
          onRemoveSave={handleRemoveCrossRefSave}
          isSaved={crossRefResult ? isCrossRefBookmarked(crossRefResult.fileAName, crossRefResult.fileBName) : false}
        />
      )}
      {showNarrativeMapper && (
        <NarrativeMapper 
          onClose={() => setShowNarrativeMapper(false)} 
          onGenerate={handleNarrativeGeneration}
        />
      )}
    </div>
  );
}

import React from 'react';
import GavelIcon from './icons/GavelIcon'; 
import SparklesIcon from './icons/SparklesIcon'; 
import BrainCircuitIcon from './icons/BrainCircuitIcon';

interface IntelligentAnalysisProps {
  onAnalysisClick: (prompt: string) => void;
}

const ANALYSIS_PROMPTS = [
    { id: 'tendencies', text: 'Judge Tendencies', icon: GavelIcon },
    { id: 'loopholes', text: 'Procedural Loops', icon: SparklesIcon },
    { id: 'strategy', text: 'Legal Strategy', icon: BrainCircuitIcon },
];

export default function IntelligentAnalysis({ onAnalysisClick }: IntelligentAnalysisProps): React.ReactNode {
  return (
    <div className="pt-12 mt-12 border-t border-[#6e501a]/20">
      <div className="flex items-center gap-4 mb-10">
        <div className="h-px flex-grow bg-gradient-to-r from-transparent to-[#6e501a]/40"></div>
        <h4 className="text-[10px] font-black text-[#6e501a] uppercase tracking-[0.4em] whitespace-nowrap">
          Neural Deep Dives
        </h4>
        <div className="h-px flex-grow bg-gradient-to-l from-transparent to-[#6e501a]/40"></div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
        {ANALYSIS_PROMPTS.map((prompt) => {
          const Icon = prompt.icon;
          return (
            <button
              key={prompt.id}
              onClick={() => onAnalysisClick(prompt.text)}
              className="flex flex-col items-center justify-center gap-4 p-8 bg-[#0d0d0d] border border-[#6e501a]/30 hover:border-[#b5892f] hover:bg-[#b5892f]/5 transition-all duration-500 group relative overflow-hidden"
            >
              {/* Animated Corner accent */}
              <div className="absolute top-0 right-0 w-8 h-8 opacity-0 group-hover:opacity-100 transition-opacity">
                <div className="absolute top-0 right-0 w-px h-full bg-[#b5892f]"></div>
                <div className="absolute top-0 right-0 w-full h-px bg-[#b5892f]"></div>
              </div>

              <div className="p-4 bg-[#050505] border border-[#6e501a]/40 group-hover:border-[#b5892f] group-hover:bg-[#1a1a1a] transition-all duration-300 text-[#b5892f]">
                <Icon className="w-8 h-8 group-hover:scale-110 transition-transform" />
              </div>
              <span className="text-[10px] font-black text-[#a0a0a0] group-hover:text-[#e2c07d] uppercase tracking-[0.2em] transition-colors text-center">
                {prompt.text}
              </span>
            </button>
          );
        })}
