import CalendarIcon from './icons/CalendarIcon';
import GlobeIcon from './icons/GlobeIcon';
import ScaleIcon from './icons/ScaleIcon';
import { MAX_QUERY_LENGTH } from '../constants';
import { getHistory, clearHistory as clearHistoryService } from '../services/historyService';

// Suggestion Bank for common Denver Judicial terms and patterns
const SUGGESTION_BANK = [
  "Judge Christopher Baumann",
  "Judge Elizabeth Leith",
  "Judge Michael Vallejos",
  "Judge Shelley Gilman",
  "Judge Kandace Gerdes",
  "Denver District Court civil filing fees",
  "Denver County Court traffic procedures",
  "Motion to Dismiss for failure to state a claim",
  "Discovery Request guidelines Colorado",
  "Summary Judgment standards C.R.C.P. 56",
  "Evidentiary Hearing preparation",
  "Initial Status Conference Denver District",
  "Writ of Mandamus Colorado",
  "C.R.C.P. Rule 12(b)(5) motion",
  "Criminal Defense strategy for DUI",
  "Civil Litigation damages assessment",
  "Family Law custody patterns",
  "Probate estate planning Colorado",
