];

interface SearchFormProps {
  params: SearchParams;
  setParams: React.Dispatch<React.SetStateAction<SearchParams>>;
  onSearch: () => void;
  isLoading: boolean;
  onClear: () => void;
  onSelectHistory: (params: SearchParams) => void;
  onSave: () => void;
  canSave: boolean;
}

export default function SearchForm({ params, setParams, onSearch, isLoading, onClear, onSelectHistory }: SearchFormProps): React.ReactNode {
  const [isAdvancedOpen, setIsAdvancedOpen] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [history, setHistory] = useState<SearchParams[]>([]);

  // Suggestion State
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [activeSuggestionIndex, setActiveSuggestionIndex] = useState(-1);
  const [showSuggestions, setShowSuggestions] = useState(false);

  const historyRef = useRef<HTMLDivElement>(null);
  const suggestionRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const cardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (isHistoryOpen) setHistory(getHistory());
  }, [isHistoryOpen]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (historyRef.current && !historyRef.current.contains(event.target as Node)) setIsHistoryOpen(false);
      if (suggestionRef.current && !suggestionRef.current.contains(event.target as Node)) setShowSuggestions(false);
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useLayoutEffect(() => {
    const textarea = textareaRef.current;
    if (textarea) {
      textarea.style.height = 'auto';
      textarea.style.height = `${Math.max(120, textarea.scrollHeight)}px`;
    }
  }, [params.query]);

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    const card = cardRef.current;
    if (!card) return;
    const rect = card.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    const centerX = rect.width / 2;
    const centerY = rect.height / 2;

    const rotateX = (y - centerY) / 80;
    const rotateY = (centerX - x) / 80;

    card.style.transform = `perspective(1200px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) translateY(-4px)`;
  };

  const handleMouseLeave = () => {
    if (cardRef.current) {
      cardRef.current.style.transform = `perspective(1200px) rotateX(0deg) rotateY(0deg) translateY(0px)`;
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const value = e.target.value;
    setParams(prev => ({ ...prev, query: value }));

    // Simple fuzzy matching/filtering
    if (value.trim().length > 1) {
      const filtered = SUGGESTION_BANK.filter(item => 
        item.toLowerCase().includes(value.toLowerCase()) && item !== value
      ).slice(0, 5);
      setSuggestions(filtered);
      setShowSuggestions(filtered.length > 0);
    } else {
      setShowSuggestions(false);
    }
    setActiveSuggestionIndex(-1);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (showSuggestions) {
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        setActiveSuggestionIndex(prev => (prev < suggestions.length - 1 ? prev + 1 : prev));
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        setActiveSuggestionIndex(prev => (prev > 0 ? prev - 1 : -1));
      } else if (e.key === 'Enter' && activeSuggestionIndex !== -1) {
        e.preventDefault();
        selectSuggestion(suggestions[activeSuggestionIndex]);
        return;
      } else if (e.key === 'Escape') {
        setShowSuggestions(false);
      }
    }

    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      if (params.query.trim()) onSearch();
    }
  };

  const selectSuggestion = (text: string) => {
    setParams(prev => ({ ...prev, query: text }));
    setShowSuggestions(false);
    setActiveSuggestionIndex(-1);
    if (textareaRef.current) textareaRef.current.focus();
  };

  const handleHistoryItemClick = (item: SearchParams) => {
    onSelectHistory(item);
    setIsHistoryOpen(false);
  };

  const handleClearHistory = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm('Wipe all strategic logs?')) {
      clearHistoryService();
      setHistory([]);
    }
  };

  return (
    <div 
      ref={cardRef}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      className="case-card-base rounded-none p-8 sm:p-12 group/card transition-transform duration-500 ease-out border-b border-[#5e5239]/20"
    >
      <div className="grain-overlay"></div>
      <div className="mechanism-rail"><div className="counterweight"></div></div>
      <div className="pivot"></div>

      <form onSubmit={(e) => { e.preventDefault(); onSearch(); }} className="relative z-10">
        <div className="flex flex-col gap-8">

          {/* Header & History Toggle */}
          <div className="flex justify-between items-end border-b border-[#5e5239]/10 pb-4">
            <div className="flex items-center gap-3">
              <div className="w-2 h-2 bg-[#a18d66] rounded-sm rotate-45 animate-pulse shadow-[0_0_8px_#a18d66]"></div>
              <label className="text-[11px] font-black uppercase tracking-[0.4em] text-[#999999]">Adversarial Input Console</label>
            </div>
            <button 
              type="button" 
              onClick={() => setIsHistoryOpen(!isHistoryOpen)} 
              className="text-[#a18d66] hover:text-[#d1c19d] transition-all flex items-center gap-2 group/hist"
            >
              <HistoryIcon className="w-4 h-4 group-hover/hist:scale-110 transition-transform" />
              <span className="text-[10px] font-bold uppercase tracking-[0.2em]">Dossier History</span>
            </button>
          </div>

          {/* Query Area */}
          <div className="relative group/query">
            <div className="absolute -inset-0.5 bg-[#a18d66]/5 opacity-0 group-focus-within/query:opacity-100 transition-opacity pointer-events-none rounded-sm"></div>
            <textarea
              ref={textareaRef}
              value={params.query}
              onChange={handleInputChange}
              onKeyDown={handleKeyDown}
              onFocus={() => { if (suggestions.length > 0) setShowSuggestions(true); }}
              placeholder="Input case variables, judge names, or strategic queries..."
              className="w-full bg-[#050505] border border-[#5e5239]/30 p-8 font-mono-legal text-[#d1c19d] text-xl focus:outline-none focus:border-[#a18d66] transition-all min-h-[140px] placeholder:text-[#5e5239]/20 resize-none overflow-hidden shadow-[inset_0_4px_12px_rgba(0,0,0,0.8)]"
              disabled={isLoading}
              maxLength={MAX_QUERY_LENGTH}
            />

            {/* Character Count */}
            <div className="absolute bottom-4 right-6 text-[9px] font-mono text-[#5e5239]/60 uppercase tracking-widest">
