              className="flex-grow sm:flex-grow-0 px-16 py-6 bg-gradient-to-br from-[#a18d66] to-[#5e5239] text-[#050505] font-black uppercase italic tracking-tighter text-2xl hover:brightness-110 disabled:grayscale disabled:opacity-30 transition-all relative overflow-hidden group/btn shadow-[0_15px_40px_rgba(161,141,102,0.3)] border border-[#d1c19d]/20"
            >
