        {/* Collapsible Advanced Section */}
        {isAdvancedOpen && (
          <div className="mt-12 pt-12 border-t border-[#5e5239]/30 animate-[fadeIn_0.5s_ease-out]">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-10">

