                  className="w-full bg-[#050505] border border-[#5e5239]/50 text-[#d1c19d] font-mono-legal text-[11px] px-5 py-4 outline-none focus:border-[#a18d66] transition-colors appearance-none cursor-pointer shadow-xl"
