import ChevronDownIcon from './icons/ChevronDownIcon';
import HistoryIcon from './icons/HistoryIcon';
import GavelIcon from './icons/GavelIcon';
import GlobeIcon from './icons/GlobeIcon';
import ScaleIcon from './icons/ScaleIcon';
import { MAX_QUERY_LENGTH } from '../constants';
import { getHistory, clearHistory as clearHistoryService } from '../services/historyService';

const SUGGESTION_BANK = [
  "Judge Christopher Baumann tendencies",
  "Denver District Court filing deadlines",
  "Motion to Dismiss C.R.C.P. 12(b)(5)",
  "Discovery standards for pro-se litigants",
  "Denver County Court traffic hearing procedure"
];

interface SearchFormProps {
  params: SearchParams;
  setParams: React.Dispatch<React.SetStateAction<SearchParams>>;
  onSearch: () => void;
  isLoading: boolean;
  onClear: () => void;
  onSelectHistory: (params: SearchParams) => void;
  onSave: () => void;
  canSave: boolean;
}

export default function SearchForm({ params, setParams, onSearch, isLoading, onClear, onSelectHistory }: SearchFormProps): React.ReactNode {
  const [isAdvancedOpen, setIsAdvancedOpen] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);

  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useLayoutEffect(() => {
    const textarea = textareaRef.current;
    if (textarea) {
      textarea.style.height = 'auto';
      textarea.style.height = `${Math.max(80, textarea.scrollHeight)}px`;
    }
  }, [params.query]);

  const handleInputChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const value = e.target.value;
    setParams(prev => ({ ...prev, query: value }));
    if (value.length > 2) {
      const filtered = SUGGESTION_BANK.filter(s => s.toLowerCase().includes(value.toLowerCase())).slice(0, 3);
      setSuggestions(filtered);
      setShowSuggestions(filtered.length > 0);
    } else {
      setShowSuggestions(false);
    }
  };

  return (
    <div className="p-8 relative">
      <div className="flex flex-col gap-6">

        <div className="flex justify-between items-center text-[10px] font-mono-legal text-[#5e5239] uppercase tracking-[0.4em]">
          <div className="flex items-center gap-3">
            <span className="w-1.5 h-1.5 bg-[#a18d66] rounded-full animate-pulse"></span>
            Intelligence Input Console
          </div>
          <button onClick={() => setIsHistoryOpen(!isHistoryOpen)} className="hover:text-[#d1c19d] transition-colors flex items-center gap-2">
            <HistoryIcon className="w-3 h-3" />
            Archives
          </button>
        </div>

        <div className="relative group">
          <textarea
            ref={textareaRef}
            value={params.query}
            onChange={handleInputChange}
            onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), onSearch())}
            placeholder="Execute Strategic Query..."
            className="w-full bg-[#050505] border border-[#5e5239]/30 p-6 font-mono-legal text-[#d1c19d] text-lg focus:outline-none focus:border-[#a18d66] transition-all min-h-[80px] placeholder:text-[#5e5239]/20 resize-none overflow-hidden"
            disabled={isLoading}
          />

          <div className="absolute top-0 right-0 p-2 pointer-events-none">
             <div className="w-2 h-2 border-t border-r border-[#a18d66]/50"></div>
          </div>
          <div className="absolute bottom-0 left-0 p-2 pointer-events-none">
             <div className="w-2 h-2 border-b border-l border-[#a18d66]/50"></div>
          </div>

          {showSuggestions && (
            <div className="absolute left-0 top-full mt-2 w-full bg-[#0d0d0d] border border-[#a18d66]/40 z-50 p-2 flex flex-col gap-1">
              {suggestions.map((s, i) => (
                <button key={i} onClick={() => { setParams({...params, query: s}); setShowSuggestions(false); }} className="text-left p-3 hover:bg-[#a18d66]/10 text-[11px] font-mono-legal text-[#999999] hover:text-[#d1c19d] transition-colors">
                   > {s}
                </button>
              ))}
            </div>
          )}
        </div>

        <div className="flex flex-wrap items-center gap-4">
          <button 
            onClick={onSearch}
            disabled={isLoading || !params.query.trim()}
            className="flex-grow sm:flex-grow-0 px-12 py-4 bg-[#a18d66] text-[#050505] font-black uppercase italic tracking-tighter text-lg hover:brightness-110 disabled:opacity-20 transition-all flex items-center justify-center gap-4"
          >
            {isLoading ? <SpinnerIcon className="w-5 h-5" /> : 'Run Analysis'}
          </button>

          <button 
            onClick={() => setIsAdvancedOpen(!isAdvancedOpen)} 
            className={`flex items-center gap-3 px-6 py-4 border text-[10px] font-black uppercase tracking-widest transition-all ${isAdvancedOpen ? 'bg-[#a18d66]/10 border-[#a18d66] text-[#d1c19d]' : 'border-[#5e5239]/40 text-[#5e5239]'}`}
          >
            Tactical Params <ChevronDownIcon className={`w-3 h-3 transition-transform ${isAdvancedOpen ? 'rotate-180' : ''}`} />
          </button>
        </div>

        {isAdvancedOpen && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 pt-6 border-t border-[#5e5239]/20 animate-[fadeIn_0.3s_ease-out]">
            <select value={params.jurisdiction} onChange={(e) => setParams({...params, jurisdiction: e.target.value as any})} className="bg-[#050505] border border-[#5e5239]/50 text-[#d1c19d] text-[10px] p-3 outline-none focus:border-[#a18d66] font-mono-legal">
              <option value="all">JURISDICTION: GLOBAL</option>
              <option value="denver_district">DENVER DISTRICT</option>
              <option value="denver_county">DENVER COUNTY</option>
            </select>
            <select value={params.caseType} onChange={(e) => setParams({...params, caseType: e.target.value as any})} className="bg-[#050505] border border-[#5e5239]/50 text-[#d1c19d] text-[10px] p-3 outline-none focus:border-[#a18d66] font-mono-legal">
              <option value="all">PROFILE: ALL</option>
              <option value="civil">CIVIL LITIGATION</option>
              <option value="criminal">CRIMINAL DEFENSE</option>
            </select>
            <input type="text" placeholder="DOCKET ID #" value={params.caseNumber || ''} onChange={(e) => setParams({...params, caseNumber: e.target.value})} className="bg-[#050505] border border-[#5e5239]/50 text-[#d1c19d] text-[10px] p-3 outline-none focus:border-[#a18d66] font-mono-legal" />
          </div>
        )}
      </div>
    </div>
  );
}

