const SUGGESTION_BANK = [
  "Judge Christopher Baumann tendencies",
  "Denver District Court filing deadlines",
  "Motion to Dismiss C.R.C.P. 12(b)(5)",
  "Discovery standards for pro-se litigants",
  "Denver County Court traffic hearing procedure",
  "Judge Elizabeth Leith probate rulings",
  "Motion for Summary Judgment standards",
  "Initial Status Conference Denver guidelines",
  "C.R.S. Title 13 Article 1 procedures",
  "Denver Police operations manual search"
];

interface SearchFormProps {
  params: SearchParams;
  setParams: React.Dispatch<React.SetStateAction<SearchParams>>;
  onSearch: () => void;
  isLoading: boolean;
  onClear: () => void;
  onSelectHistory: (params: SearchParams) => void;
  onSave: () => void;
  canSave: boolean;
}

interface ScoredSuggestion {
  text: string;
  score: number;
}

export default function SearchForm({ params, setParams, onSearch, isLoading, onClear, onSelectHistory }: SearchFormProps): React.ReactNode {
  const [isAdvancedOpen, setIsAdvancedOpen] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [suggestions, setSuggestions] = useState<ScoredSuggestion[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [isClearing, setIsClearing] = useState(false);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const suggestionRef = useRef<HTMLDivElement>(null);

  // Fuzzy Scoring Engine: Weighted logic for tech-forward input resilience
  const calculateFuzzyScore = (input: string, target: string): number => {
    const i = input.toLowerCase();
    const t = target.toLowerCase();

    if (t === i) return 1.0;
    if (t.startsWith(i)) return 0.9;
    if (t.includes(i)) return 0.7;

    // Subsequence check for typos and shorthand
    let score = 0;
    let targetIdx = 0;
    for (let char of i) {
      const foundIdx = t.indexOf(char, targetIdx);
      if (foundIdx !== -1) {
        // Boost score based on proximity (closer characters = higher score)
        const proximityBoost = 1 / (1 + (foundIdx - targetIdx));
        score += 0.5 + (0.5 * proximityBoost);
        targetIdx = foundIdx + 1;
      }
    }

    const normalizedScore = score / i.length;
    return normalizedScore > 0.4 ? normalizedScore * 0.5 : 0;
  };

  useLayoutEffect(() => {
    const textarea = textareaRef.current;
    if (textarea) {
      textarea.style.height = 'auto';
      textarea.style.height = `${Math.max(80, textarea.scrollHeight)}px`;
    }
  }, [params.query]);

  const handleInputChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const value = e.target.value;
    setParams(prev => ({ ...prev, query: value }));

    if (value.length > 1) {
      const scored = SUGGESTION_BANK.map(s => ({
        text: s,
        score: calculateFuzzyScore(value, s)
      }))
      .filter(s => s.score > 0.2)
      .sort((a, b) => b.score - a.score)
      .slice(0, 4);

      setSuggestions(scored);
      setShowSuggestions(scored.length > 0);
    } else {
      setShowSuggestions(false);
    }
  };

  const handleClear = () => {
    setIsClearing(true);
    setTimeout(() => {
      onClear();
      setIsClearing(false);
    }, 800);
  };

  return (
    <div className="p-8 relative">
      <div className="flex flex-col gap-6">

        <div className="flex justify-between items-center text-[10px] font-mono-legal text-[#5e5239] uppercase tracking-[0.4em]">
          <div className="flex items-center gap-3">
            <span className="w-1.5 h-1.5 bg-[#a18d66] rounded-full animate-pulse shadow-[0_0_5px_#a18d66]"></span>
            Intelligence Input Console
            <span className="ml-4 opacity-40 px-2 border border-[#5e5239]/40 rounded-sm">Fuzzy_Match: ACTIVE</span>
          </div>
          <button onClick={() => setIsHistoryOpen(!isHistoryOpen)} className="hover:text-[#d1c19d] transition-colors flex items-center gap-2">
            <HistoryIcon className="w-3 h-3" />
            Archives
          </button>
        </div>

        <div className="relative group">
          <textarea
            ref={textareaRef}
            value={params.query}
            onChange={handleInputChange}
            onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), onSearch())}
            onFocus={() => suggestions.length > 0 && setShowSuggestions(true)}
            placeholder="Execute Strategic Query..."
            className="w-full bg-[#050505] border border-[#5e5239]/30 p-6 font-mono-legal text-[#d1c19d] text-lg focus:outline-none focus:border-[#a18d66] transition-all min-h-[80px] placeholder:text-[#5e5239]/20 resize-none overflow-hidden shadow-[inset_0_4px_12px_rgba(0,0,0,0.8)]"
            disabled={isLoading || isClearing}
          />

          <div className="absolute top-0 right-0 p-2 pointer-events-none">
             <div className="w-2 h-2 border-t border-r border-[#a18d66]/50"></div>
          </div>
          <div className="absolute bottom-0 left-0 p-2 pointer-events-none">
             <div className="w-2 h-2 border-b border-l border-[#a18d66]/50"></div>
          </div>

          {showSuggestions && (
            <div 
              ref={suggestionRef}
              className="absolute left-0 top-full mt-2 w-full bg-[#0d0d0d] border border-[#a18d66]/40 z-50 shadow-[0_20px_50px_rgba(0,0,0,1)] animate-[fadeIn_0.15s_ease-out]"
            >
              <div className="p-2 border-b border-[#5e5239]/20 bg-[#121212]">
                <span className="text-[8px] font-black text-[#5e5239] uppercase tracking-[0.3em]">Neural intent predictions</span>
              </div>
              <div className="flex flex-col">
                {suggestions.map((s, i) => (
                  <button 
                    key={i} 
                    onClick={() => { setParams({...params, query: s.text}); setShowSuggestions(false); }} 
                    className="group/item text-left p-4 hover:bg-[#a18d66]/10 border-b border-[#5e5239]/10 last:border-0 transition-colors flex items-center justify-between"
                  >
                     <span className="text-[11px] font-mono-legal text-[#999999] group-hover/item:text-[#d1c19d] transition-colors">
                       <span className="text-[#a18d66] mr-3 font-bold opacity-30">></span> {s.text}
                     </span>
                     <div className="flex flex-col items-end gap-1">
                        <div className="w-12 h-1 bg-[#1a1a1a] rounded-full overflow-hidden">
                           <div className="h-full bg-[#a18d66]" style={{ width: `${s.score * 100}%` }}></div>
                        </div>
                        <span className="text-[7px] font-mono text-[#5e5239] uppercase">Match_{Math.round(s.score * 100)}%</span>
                     </div>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>

        <div className="flex flex-wrap items-center gap-4">
          <button 
            onClick={onSearch}
            disabled={isLoading || !params.query.trim() || isClearing}
            className="flex-grow sm:flex-grow-0 min-w-[200px] px-12 py-4 bg-[#a18d66] text-[#050505] font-black uppercase italic tracking-tighter text-lg hover:brightness-110 disabled:opacity-20 transition-all flex items-center justify-center gap-4 relative overflow-hidden group/btn"
          >
            <div className="absolute inset-0 bg-white/10 opacity-0 group-hover/btn:opacity-100 transition-opacity"></div>
            {isLoading ? (
