import React, { useState, useCallback, useEffect } from 'react';
import { SearchType, type SearchParams, DateRange, CaseStatus, type Bookmark, type SearchBookmark, type DocumentBookmark, type CrossRefBookmark, type PartialSearchResult, type SearchResult, type DocumentAnalysisResult, type CrossReferenceResult, type NarrativeMapResult, CaseType, Jurisdiction } from './types';
import { searchWebWithGemini, analyzeDocument, crossReferenceDocuments, generateNarrativeMap } from './services/geminiService';
import { getCachedResult, setCachedResult, clearCache } from './services/cacheService';
import { addToHistory, clearHistory } from './services/historyService';
import { getBookmarks, saveBookmark, removeBookmark, isSearchBookmarked, isDocBookmarked, isCrossRefBookmarked, clearBookmarks, generateSearchKey, generateDocKey, generateCrossRefKey } from './services/bookmarkService';
import { MAX_QUERY_LENGTH, MIN_LIST_COUNT, MAX_LIST_COUNT } from './constants';
import Header from './components/Header';
import Banner from './components/Banner';
import SearchForm from './components/SearchForm';
import ResultsDisplay from './components/ResultsDisplay';
import Examples from './components/Examples';
import Bookmarks from './components/Bookmarks';
import JudgeDetailModal from './components/JudgeDetailModal';
import DocumentAnalysisModal from './components/DocumentAnalysisModal';
import CrossReferenceModal from './components/CrossReferenceModal';
import NarrativeMapper from './components/NarrativeMapper';

export default function App(): React.ReactNode {
  const [searchParams, setSearchParams] = useState<SearchParams>({
    query: '',
    searchType: SearchType.SEARCH,
    listCount: undefined,
    dateRange: DateRange.ANY,
    siteRestrict: '',
    fileType: '',
    partyName: '',
    caseNumber: '',
    caseStatus: CaseStatus.ALL,
    caseType: CaseType.ALL,
    jurisdiction: Jurisdiction.ALL,
  });
  const [currentSearchParamsForResults, setCurrentSearchParamsForResults] = useState<SearchParams | null>(null);
  const [output, setOutput] = useState<SearchResult | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);

  const [showJudgeModal, setShowJudgeModal] = useState(false);
  const [selectedJudgeName, setSelectedJudgeName] = useState<string | null>(null);

  const [showDocumentAnalysisModal, setShowDocumentAnalysisModal] = useState(false);
  const [documentAnalysisResult, setDocumentAnalysisResult] = useState<DocumentAnalysisResult | null>(null);
  const [isDocumentAnalysisLoading, setIsDocumentAnalysisLoading] = useState<boolean>(false);
  const [documentAnalysisError, setDocumentAnalysisError] = useState<string | null>(null);
  // Shared context for the document being audited
  const [auditFileData, setAuditFileData] = useState<{b64: string, mime: string, name: string} | null>(null);

  const [showCrossRefModal, setShowCrossRefModal] = useState(false);
  const [crossRefResult, setCrossRefResult] = useState<CrossReferenceResult | null>(null);
  const [isCrossRefLoading, setIsCrossRefLoading] = useState(false);
  const [crossRefError, setCrossRefError] = useState<string | null>(null);

  const [showNarrativeMapper, setShowNarrativeMapper] = useState(false);
  const [narrativeInitialData, setNarrativeInitialData] = useState<{b64: string, mime: string, name: string} | null>(null);

  useEffect(() => {
    setBookmarks(getBookmarks());
  }, []);

  const executeSearch = useCallback(async (params: SearchParams) => {
    const finalParams: SearchParams = { ...params, query: params.query.trim() };

    if (!finalParams.query) {
      setError('Neural scan requires query input.');
      return;
    }
    if (finalParams.query.length > MAX_QUERY_LENGTH) {
      setError(`Payload exceeds char limit.`);
      return;
    }

    const cachedResult = getCachedResult(finalParams);
    if (cachedResult) {
      setOutput({
        ...cachedResult,
        isSummaryStreaming: false,
        isFollowUpQuestionsLoading: false,
        isRelatedQueriesLoading: false,
        isTimelineLoading: false,
        isIdentifiedJudgesLoading: false,
      });
      setCurrentSearchParamsForResults(finalParams);
      setError(null);
      return;
    }

    setIsLoading(true);
    setError(null);
    setOutput({
      summary: '',
      sources: [],
      followUpQuestions: [],
      relatedQueries: [],
      timelineEvents: [],
      identifiedJudges: [],
      isSummaryStreaming: true,
      isFollowUpQuestionsLoading: false,
      isRelatedQueriesLoading: false,
      isTimelineLoading: false,
      isIdentifiedJudgesLoading: false,
    });
    setCurrentSearchParamsForResults(finalParams);

    try {
      const result = await searchWebWithGemini(finalParams, (partial) => {
        setOutput(prev => ({ ...prev!, ...partial }));
      });
      setOutput(prev => ({
          ...prev!,
          ...result,
          isSummaryStreaming: false,
      }));
      setCachedResult(finalParams, result);
      addToHistory(finalParams);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Dossier synthesis failure.');
      setOutput(null);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const handleSearch = useCallback(() => executeSearch(searchParams), [searchParams, executeSearch]);

  const handleSaveResult = (params: SearchParams, result: SearchResult) => {
    const key = generateSearchKey(params);
    saveBookmark({ key, type: 'search', params, result, savedAt: Date.now() });
    setBookmarks(getBookmarks());
  };

  const handleRemoveSave = (params: SearchParams) => {
    removeBookmark(generateSearchKey(params));
    setBookmarks(getBookmarks());
  };

  const handleViewBookmark = (bookmark: Bookmark) => {
    if (bookmark.type === 'search') {
        setSearchParams(bookmark.params);
        setOutput({ ...bookmark.result, isSummaryStreaming: false });
        setCurrentSearchParamsForResults(bookmark.params);
    } else if (bookmark.type === 'document_analysis') {
        setDocumentAnalysisResult(bookmark.result);
        setShowDocumentAnalysisModal(true);
    } else if (bookmark.type === 'cross_reference') {
        setCrossRefResult(bookmark.result);
        setShowCrossRefModal(true);
    }
  };

  const launchNarrativeFromAudit = () => {
    if (!auditFileData) return;
    setNarrativeInitialData(auditFileData);
    setShowDocumentAnalysisModal(false);
    setShowNarrativeMapper(true);
  };

  return (
    <div className="min-h-screen pb-12 flex flex-col">
      <Banner />

      <div className="flex-grow flex flex-col lg:flex-row max-w-[1800px] mx-auto w-full px-4 lg:px-8 gap-8 mt-8">

        {/* Sidebar: Navigation & Assets */}
        <aside className="lg:w-80 flex flex-col gap-8 order-2 lg:order-1">
          <div className="tech-card p-6 flex flex-col gap-8">
            <div className="bracket-tl"></div><div className="bracket-tr"></div>
            <div className="bracket-bl"></div><div className="bracket-br"></div>

            <Header 
              onAnalyzeDocumentClick={() => { setAuditFileData(null); setShowDocumentAnalysisModal(true); }} 
              onCrossReferenceClick={() => setShowCrossRefModal(true)} 
              onNarrativeMapperClick={() => { setNarrativeInitialData(null); setShowNarrativeMapper(true); }}
            />
          </div>

          <Bookmarks 
            bookmarks={bookmarks}
            onView={handleViewBookmark}
            onDelete={(key) => { removeBookmark(key); setBookmarks(getBookmarks()); }}
          />
        </aside>

        {/* Main Console */}
        <main className="flex-grow flex flex-col gap-8 order-1 lg:order-2">
          <div className="tech-card overflow-hidden">
            <div className="bracket-tl"></div><div className="bracket-tr"></div>
            <div className="bracket-bl"></div><div className="bracket-br"></div>
            <div className="scanline"></div>

            <SearchForm
              params={searchParams}
              setParams={setSearchParams}
              onSearch={handleSearch}
              isLoading={isLoading}
              onClear={() => { setOutput(null); setSearchParams({...searchParams, query: ''}); }}
              onSelectHistory={(p) => { setSearchParams(p); executeSearch(p); }}
              onSave={() => currentSearchParamsForResults && output && handleSaveResult(currentSearchParamsForResults, output)}
              canSave={!!output && !!currentSearchParamsForResults}
            />

            <div className="px-8 pb-8 border-t border-[#5e5239]/20 pt-6">
              <Examples onSelectExample={(ex) => setSearchParams({...searchParams, ...ex})} />
            </div>
          </div>

          {error && (
            <div className="tech-card p-4 border-red-900/50 bg-red-950/10 text-red-400 font-mono-legal text-xs animate-pulse">
              <div className="flex items-center gap-3">
                <span className="w-2 h-2 bg-red-500 rounded-full"></span>
                SYSTEM_CRITICAL: {error}
              </div>
            </div>
          )}

          <ResultsDisplay
            output={output}
            searchParams={currentSearchParamsForResults}
            isLoading={isLoading}
            onQuestionClick={(q) => { setSearchParams({...searchParams, query: q}); executeSearch({...searchParams, query: q}); }}
            onAnalysisClick={(prompt) => { /* logic */ }}
            onSave={handleSaveResult}
            onRemoveSave={handleRemoveSave}
            isSaved={currentSearchParamsForResults ? isSearchBookmarked(currentSearchParamsForResults) : false}
            onJudgeClick={(name) => { setSelectedJudgeName(name); setShowJudgeModal(true); }}
          />
        </main>
      </div>

      <footer className="mt-12 text-center text-[10px] font-mono-legal text-[#5e5239] uppercase tracking-[0.4em]">
        Tactical Intelligence Node • Gemini Protocol v3.1
      </footer>

      {showJudgeModal && selectedJudgeName && (
        <JudgeDetailModal judgeName={selectedJudgeName} onClose={() => setShowJudgeModal(false)} />
      )}
      {showDocumentAnalysisModal && (
        <DocumentAnalysisModal
          onClose={() => setShowDocumentAnalysisModal(false)}
          onAnalyze={async (b64, mime, name) => {
            setAuditFileData({b64, mime, name});
            setIsDocumentAnalysisLoading(true);
            try { setDocumentAnalysisResult(await analyzeDocument(b64, mime, name)); }
            catch (e) { console.error(e); }
            finally { setIsDocumentAnalysisLoading(false); }
          }}
          result={documentAnalysisResult}
          isLoading={isDocumentAnalysisLoading}
          error={null}
          onSave={(res) => {
            saveBookmark({
              key: generateDocKey(res.fileName),
              type: 'document_analysis',
              result: res,
              savedAt: Date.now()
            });
            setBookmarks(getBookmarks());
          }}
          onRemoveSave={(r) => {
            removeBookmark(generateDocKey(r.fileName));
            setBookmarks(getBookmarks());
          }}
          onMapNarrative={launchNarrativeFromAudit}
          isSaved={documentAnalysisResult ? isDocBookmarked(documentAnalysisResult.fileName) : false}
        />
      )}
      {showCrossRefModal && (
        <CrossReferenceModal
          onClose={() => setShowCrossRefModal(false)}
          onAnalyze={async (a, am, an, b, bm, bn) => {
            setIsCrossRefLoading(true);
            try { setCrossRefResult(await crossReferenceDocuments(a, am, an, b, bm, bn)); }
            catch(e) { console.error(e); }
            finally { setIsCrossRefLoading(false); }
          }}
          result={crossRefResult}
          isLoading={isCrossRefLoading}
          error={null}
          onSave={(res) => {
            saveBookmark({
              key: generateCrossRefKey(res.fileAName, res.fileBName),
              type: 'cross_reference',
              result: res,
              savedAt: Date.now()
            });
            setBookmarks(getBookmarks());
          }}
          onRemoveSave={(r) => {
            removeBookmark(generateCrossRefKey(r.fileAName, r.fileBName));
            setBookmarks(getBookmarks());
          }}
          isSaved={crossRefResult ? isCrossRefBookmarked(crossRefResult.fileAName, crossRefResult.fileBName) : false}
        />
      )}
      {showNarrativeMapper && (
        <NarrativeMapper 
          onClose={() => { setShowNarrativeMapper(false); setNarrativeInitialData(null); }} 
          initialData={narrativeInitialData}
          onGenerate={async (b, m, n) => await generateNarrativeMap(b, m, n)}
        />
      )}
    </div>
  );
}

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { DocumentAnalysisResult } from '../types';
import { askDocumentQuestion } from '../services/geminiService';
import SpinnerIcon from './icons/SpinnerIcon';
import DocumentIcon from './icons/DocumentIcon';
import CloseIcon from './icons/CloseIcon';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import GavelIcon from './icons/GavelIcon';
import CalendarIcon from './icons/CalendarIcon';
import UserIcon from './icons/UserIcon';
import NumberIcon from './icons/NumberIcon';
import BrainCircuitIcon from './icons/BrainCircuitIcon';
import BookmarkIcon from './icons/BookmarkIcon';
import BookmarkFilledIcon from './icons/BookmarkFilledIcon';
import QuestionMarkIcon from './icons/QuestionMarkIcon';
import ScaleIcon from './icons/ScaleIcon';

interface DocumentAnalysisModalProps {
    onClose: () => void;
    onAnalyze: (base64Content: string, mimeType: string, fileName: string) => Promise<void>;
    result: DocumentAnalysisResult | null;
    isLoading: boolean;
    error: string | null;
    onSave: (result: DocumentAnalysisResult) => void;
    onRemoveSave: (result: DocumentAnalysisResult) => void;
    onMapNarrative?: () => void;
    isSaved: boolean;
}

const ProcessingView: React.FC = () => {
    const [progress, setProgress] = React.useState(0);
    const [messageIndex, setMessageIndex] = React.useState(0);

    const messages = [
        "Decrypting document structure...",
        "Identifying adversarial parties...",
        "Extracting high-leverage arguments...",
        "Cross-referencing judicial patterns...",
        "Finalizing strategic audit..."
    ];

    React.useEffect(() => {
        const timer = setInterval(() => {
            setProgress((oldProgress) => {
                if (oldProgress >= 90) return 90;
                const remaining = 90 - oldProgress;
                const step = Math.max(0.5, remaining * 0.1); 
                return Math.min(oldProgress + step, 90);
            });
        }, 200);

        const msgTimer = setInterval(() => {
             setMessageIndex(prev => (prev + 1) % messages.length);
        }, 2500);

        return () => {
            clearInterval(timer);
            clearInterval(msgTimer);
        };
    }, []);

    return (
        <div className="flex flex-col items-center justify-center py-24 px-6 animate-[fadeIn_0.5s_ease-in-out] bg-[#050505]">
            <div className="relative w-28 h-28 mb-10">
                <div className="absolute inset-0 rounded-full border-2 border-[#6e501a]/30"></div>
                <div className="absolute inset-0 rounded-full border-2 border-transparent border-t-[#b5892f] animate-spin"></div>
                <div className="absolute inset-0 flex items-center justify-center">
                    <BrainCircuitIcon className="w-12 h-12 text-[#b5892f] animate-pulse" />
                </div>
            </div>

            <h3 className="text-2xl font-black text-[#efefef] uppercase tracking-[0.2em] mb-4 italic">Neural Audit Active</h3>

            <div className="h-6 mb-10">
                <p className="text-[#e2c07d] font-mono text-[10px] uppercase tracking-widest text-center">
                    {messages[messageIndex]}
                </p>
            </div>

            <div className="w-full max-w-sm h-px bg-[#6e501a]/30 rounded-full overflow-hidden mb-4">
                <div 
                    className="h-full bg-[#b5892f] transition-all duration-300 ease-out"
                    style={{ width: `${progress}%` }}
                ></div>
            </div>

            <p className="text-[9px] text-[#6e501a] font-black uppercase tracking-[0.3em]">
                Bypassing Procedural Obscurity... {Math.round(progress)}%
            </p>
        </div>
    );
};

const getEntityIcon = (type: string) => {
  switch (type) {
    case 'judge': return <GavelIcon className="w-4 h-4 mr-2 text-[#b5892f]" />;
    case 'party': return <UserIcon className="w-4 h-4 mr-2 text-[#e2c07d]" />;
    case 'date': return <CalendarIcon className="w-4 h-4 mr-2 text-[#6e501a]" />;
    case 'case_number': return <NumberIcon className="w-4 h-4 mr-2 text-[#b5892f]" />;
    default: return <DocumentIcon className="w-4 h-4 mr-2 text-[#6e501a]" />;
  }
}

interface ChatMessage {
    role: 'user' | 'ai';
    content: string;
}

export default function DocumentAnalysisModal({ onClose, onAnalyze, result, isLoading, error, onSave, onRemoveSave, isSaved, onMapNarrative }: DocumentAnalysisModalProps): React.ReactNode {
    const [selectedFile, setSelectedFile] = useState<File | null>(null);
    const [dragActive, setDragActive] = useState(false);
    const inputRef = useRef<HTMLInputElement>(null);
    const [localError, setLocalError] = useState<string | null>(null);
    const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
    const [questionInput, setQuestionInput] = useState('');
    const [isAsking, setIsAsking] = useState(false);
    const chatEndRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (chatEndRef.current) chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }, [chatHistory, isAsking]);

    const handleFileChange = useCallback((files: FileList | null) => {
        setLocalError(null);
        if (files && files.length > 0) {
            const file = files[0];
            if (file.type !== 'application/pdf') {
                setLocalError('Invalid Mime Type: Use PDF only.');
                setSelectedFile(null);
                return;
            }
            setSelectedFile(file);
        }
    }, []);

    const handleAnalyzeClick = useCallback(async () => {
        if (!selectedFile) return;
        try {
            const base64Content = await new Promise<string>((resolve, reject) => {
                const reader = new FileReader();
                reader.onload = (e) => resolve((e.target?.result as string).split(',')[1]);
                reader.onerror = () => reject(new Error("Read Failure"));
                reader.readAsDataURL(selectedFile);
            });
            await onAnalyze(base64Content, selectedFile.type, selectedFile.name);
        } catch (e) {
             setLocalError("Audit Initialisation Failed.");
        }
    }, [selectedFile, onAnalyze]);

    const handleAskQuestion = async () => {
        if (!questionInput.trim() || !result) return;
        const userQ = questionInput.trim();
        setQuestionInput('');
        setChatHistory(prev => [...prev, { role: 'user', content: userQ }]);
        setIsAsking(true);
        try {
            const answer = await askDocumentQuestion(result, userQ);
            setChatHistory(prev => [...prev, { role: 'ai', content: answer }]);
        } catch (err) {
            setChatHistory(prev => [...prev, { role: 'ai', content: "Neural Link Interrupted. Try again." }]);
        } finally {
            setIsAsking(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-[#050505]/95 backdrop-blur-md flex justify-center items-center z-50 p-4" onClick={(e) => e.target === e.currentTarget && onClose()}>
            <div className="bg-[#121212] border border-[#6e501a] shadow-[0_40px_100px_rgba(0,0,0,1)] max-w-3xl w-full max-h-[90vh] overflow-y-auto relative custom-scrollbar">
                <div className="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-[#6e501a] via-[#b5892f] to-[#6e501a]"></div>

                <div className="flex justify-between items-center p-6 border-b border-[#6e501a]/20">
                    <h2 className="text-xl font-black text-[#efefef] uppercase tracking-[0.2em] italic flex items-center">
                        <DocumentIcon className="w-6 h-6 mr-4 text-[#b5892f]" />
                        Strategic Evidence Audit
                    </h2>
                    <div className="flex items-center gap-4">
                        {result && (
                            <button onClick={() => isSaved ? onRemoveSave(result) : onSave(result)} className="text-[#b5892f] hover:text-[#e2c07d] transition-colors">
                                {isSaved ? <BookmarkFilledIcon className="w-6 h-6" /> : <BookmarkIcon className="w-6 h-6" />}
                            </button>
                        )}
                        <button onClick={onClose} className="text-[#6e501a] hover:text-[#efefef] transition-colors"><CloseIcon className="w-6 h-6" /></button>
                    </div>
                </div>

                <div className="p-8">
                    {!result && !isLoading ? (
                        <div className="space-y-10">
                            <div
                                onDragOver={(e) => {e.preventDefault(); setDragActive(true);}}
                                onDragLeave={() => setDragActive(false)}
                                onDrop={(e) => {e.preventDefault(); setDragActive(false); handleFileChange(e.dataTransfer.files);}}
                                onClick={() => inputRef.current?.click()}
                                className={`flex flex-col items-center justify-center p-12 border border-dashed transition-all cursor-pointer ${
                                    dragActive ? 'border-[#b5892f] bg-[#b5892f]/5 shadow-inner' : 'border-[#6e501a]/30 bg-[#050505] hover:border-[#b5892f]/50'
                                }`}
                            >
                                <input ref={inputRef} type="file" accept="application/pdf" onChange={(e) => handleFileChange(e.target.files)} className="hidden" />
                                <DocumentIcon className="w-14 h-14 text-[#6e501a] mb-6 group-hover:scale-110 transition-transform" />
                                <p className="text-sm font-bold text-[#e2c07d] uppercase tracking-widest text-center">
                                    Inject Source Dossier (PDF)
                                </p>
                                <p className="text-[10px] text-[#6e501a] mt-2 font-mono uppercase">Max Payload: 10MB</p>
                                {selectedFile && <p className="mt-6 text-xs text-white font-black uppercase tracking-widest bg-[#b5892f] px-3 py-1">{selectedFile.name}</p>}
                            </div>
                            <button
                                onClick={handleAnalyzeClick}
                                disabled={!selectedFile || isLoading}
                                className="w-full py-5 bg-[#b5892f] text-[#050505] font-black uppercase italic tracking-tighter text-xl hover:bg-[#e2c07d] transition-all disabled:opacity-30 shadow-xl"
                            >
                                Execute Intelligence Harvest
                            </button>
                        </div>
                    ) : isLoading ? (
                        <ProcessingView />
                    ) : result ? (
                        <div className="space-y-12 animate-[fadeIn_0.5s_ease-out]">
                            <div className="flex flex-col sm:flex-row gap-6">
                                <div className="flex-grow p-8 bg-[#050505] border-l-4 border-[#b5892f] shadow-inner">
