import React, { useState, useEffect, useRef, useLayoutEffect } from 'react';
import { SearchType, type SearchParams, DateRange, CaseStatus, CaseType, Jurisdiction } from '../types';
import SpinnerIcon from './icons/SpinnerIcon';
import ChevronDownIcon from './icons/ChevronDownIcon';
import HistoryIcon from './icons/HistoryIcon';
import { MAX_QUERY_LENGTH } from '../constants';

const SUGGESTION_BANK = [
  "Judge Christopher Baumann tendencies",
  "Denver District Court filing deadlines",
  "Motion to Dismiss C.R.C.P. 12(b)(5)",
  "Discovery standards for pro-se litigants",
  "Denver Police operations manual search",
  "Judge Michael Vallejos criminal rulings",
  "Denver District Attorney case portal",
];

interface SearchFormProps {
  params: SearchParams;
  setParams: React.Dispatch<React.SetStateAction<SearchParams>>;
  onSearch: () => void;
  isLoading: boolean;
  onClear: () => void;
}

export default function SearchForm({ params, setParams, onSearch, isLoading, onClear }: SearchFormProps): React.ReactNode {
  const [isAdvancedOpen, setIsAdvancedOpen] = useState(false);
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(-1);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const suggestionRef = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    const textarea = textareaRef.current;
    if (textarea) {
      textarea.style.height = 'auto';
      textarea.style.height = `${Math.max(120, textarea.scrollHeight)}px`;
    }
  }, [params.query]);

  const handleInputChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const value = e.target.value;
    setParams(prev => ({ ...prev, query: value }));

    if (value.length > 2) {
      const filtered = SUGGESTION_BANK.filter(s => s.toLowerCase().includes(value.toLowerCase())).slice(0, 5);
      setSuggestions(filtered);
      setShowSuggestions(filtered.length > 0);
    } else {
      setShowSuggestions(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (showSuggestions) {
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        setSelectedIndex(prev => (prev < suggestions.length - 1 ? prev + 1 : prev));
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        setSelectedIndex(prev => (prev > 0 ? prev - 1 : -1));
      } else if (e.key === 'Enter' && selectedIndex >= 0) {
        e.preventDefault();
        selectSuggestion(suggestions[selectedIndex]);
      } else if (e.key === 'Escape') {
        setShowSuggestions(false);
      } else if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        onSearch();
      }
    } else if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      onSearch();
    }
  };

  const selectSuggestion = (text: string) => {
    setParams(prev => ({ ...prev, query: text }));
    setShowSuggestions(false);
    setSelectedIndex(-1);
    textareaRef.current?.focus();
  };

  return (
    <div className="p-8 bg-[#000000] border-b-2 border-[#00ff41] relative">
      <div className="absolute top-0 right-0 p-2 opacity-10 font-mono text-[8px] pointer-events-none">
        7F 45 4C 46 02 01 01 00 00 00 00 00 00 00 00 00 03 00 3E 00 01 00 00 00 10 11 40 00 00 00 00 00
      </div>

      <div className="flex flex-col gap-6">
        <div className="flex justify-between items-center text-[9px] font-mono text-[#aa00ff] uppercase tracking-[0.4em]">
          <div className="flex items-center gap-3">
            <span className="w-1.5 h-1.5 bg-[#ff0033] animate-ping"></span>
            TARGET_ACQUISITION_TERMINAL
          </div>
          <div className="flex items-center gap-6">
             <span className="text-[#00ff41]/60">ID: DNVR_COURT_0x82</span>
             <HistoryIcon className="w-3 h-3" />
          </div>
        </div>

        <div className="relative group" ref={suggestionRef}>
          <textarea
            ref={textareaRef}
            value={params.query}
            onChange={handleInputChange}
            onKeyDown={handleKeyDown}
            placeholder="INPUT_SELECTOR_HERE..."
            className="w-full bg-black border-2 border-[#00ff41] p-6 font-mono text-[#00ff41] text-xl focus:outline-none focus:bg-[#00ff41]/5 transition-all min-h-[120px] placeholder:text-[#00ff41]/20 resize-none overflow-hidden"
            disabled={isLoading}
          />

          <div className="absolute top-0 right-0 p-2 pointer-events-none">
             <div className="w-4 h-4 border-t-2 border-r-2 border-[#ff0033]"></div>
          </div>
          <div className="absolute bottom-0 left-0 p-2 pointer-events-none">
             <div className="w-4 h-4 border-b-2 border-l-2 border-[#aa00ff]"></div>
          </div>

          {showSuggestions && (
            <div className="absolute left-0 top-full mt-2 w-full bg-black border-2 border-[#aa00ff] z-50 shadow-[0_0_30px_rgba(170,0,255,0.2)]">
              <div className="p-2 border-b border-[#aa00ff]/20 bg-[#aa00ff]/10">
                <span className="text-[8px] font-black text-[#aa00ff] uppercase tracking-[0.3em]">PROBABLE_MATCHES</span>
              </div>
              <div className="flex flex-col">
                {suggestions.map((s, i) => (
                  <button 
                    key={i} 
                    onClick={() => selectSuggestion(s)}
                    onMouseEnter={() => setSelectedIndex(i)}
                    className={`text-left p-4 border-b border-[#aa00ff]/10 last:border-0 transition-colors text-[11px] font-mono ${selectedIndex === i ? 'bg-[#aa00ff] text-black' : 'text-[#aa00ff]'}`}
                  >
                    >> {s}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>

        <div className="flex flex-wrap items-center gap-4">
          <button 
            onClick={onSearch}
            disabled={isLoading || !params.query.trim()}
            className="flex-grow px-12 py-5 bg-[#00ff41] text-black font-black uppercase italic tracking-tighter text-2xl hover:bg-[#aa00ff] disabled:opacity-20 transition-all flex items-center justify-center gap-4 relative overflow-hidden group/btn"
          >
            {isLoading ? (
              <>
                <SpinnerIcon className="w-6 h-6 text-black" />
                <span className="animate-pulse">COLLECTING_SIGINT...</span>
              </>
            ) : '[RUN_QUERY]'}
          </button>

          <button 
            onClick={() => setIsAdvancedOpen(!isAdvancedOpen)} 
            className={`px-8 py-5 border-2 text-[10px] font-black uppercase tracking-widest transition-all ${isAdvancedOpen ? 'bg-[#aa00ff] border-[#aa00ff] text-black' : 'border-[#00ff41] text-[#00ff41]'}`}
          >
            [SELECTORS_FILTERS] {isAdvancedOpen ? '-' : '+'}
          </button>
        </div>

        {isAdvancedOpen && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 pt-6 border-t-2 border-[#00ff41]/20 animate-glitch">
            <div className="space-y-2">
              <label className="text-[9px] font-black text-[#aa00ff] uppercase tracking-widest">GEO_SECTOR</label>
              <select value={params.jurisdiction} onChange={(e) => setParams({...params, jurisdiction: e.target.value as any})} className="w-full bg-black border border-[#aa00ff] text-[#aa00ff] text-[10px] p-3 outline-none focus:bg-[#aa00ff]/10 appearance-none cursor-pointer">
                <option value="all">ANY_SECTOR</option>
                <option value="denver_district">DNVR_DIST</option>
                <option value="denver_county">DNVR_CNTY</option>
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-[9px] font-black text-[#aa00ff] uppercase tracking-widest">OBJ_CLASS</label>
              <select value={params.caseType} onChange={(e) => setParams({...params, caseType: e.target.value as any})} className="w-full bg-black border border-[#aa00ff] text-[#aa00ff] text-[10px] p-3 outline-none focus:bg-[#aa00ff]/10 appearance-none cursor-pointer">
                <option value="all">ALL_OBJECTS</option>
                <option value="civil">CIVIL_FILINGS</option>
                <option value="criminal">CRIM_DOCKET</option>
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-[9px] font-black text-[#aa00ff] uppercase tracking-widest">NODE_ID</label>
              <input type="text" placeholder="0x_CASE_NUM" value={params.caseNumber || ''} onChange={(e) => setParams({...params, caseNumber: e.target.value})} className="w-full bg-black border border-[#aa00ff] text-[#aa00ff] text-[10px] p-3 outline-none focus:bg-[#aa00ff]/10 placeholder:text-[#aa00ff]/30" />
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

