import React, { useState, useEffect, useRef, useLayoutEffect } from 'react';
import { SearchType, type SearchParams, DateRange, CaseStatus, CaseType, Jurisdiction } from '../types';
import SpinnerIcon from './icons/SpinnerIcon';
import ChevronDownIcon from './icons/ChevronDownIcon';
import HistoryIcon from './icons/HistoryIcon';
import GavelIcon from './icons/GavelIcon';
import GlobeIcon from './icons/GlobeIcon';
import ScaleIcon from './icons/ScaleIcon';
import { MAX_QUERY_LENGTH } from '../constants';
import { getHistory, clearHistory as clearHistoryService } from '../services/historyService';

const SUGGESTION_BANK = [
  "Judge Christopher Baumann tendencies",
  "Denver District Court filing deadlines",
  "Motion to Dismiss C.R.C.P. 12(b)(5)",
  "Discovery standards for pro-se litigants",
  "Denver County Court traffic hearing procedure",
  "Judge Elizabeth Leith probate rulings",
  "Motion for Summary Judgment standards",
  "Initial Status Conference Denver guidelines",
  "C.R.S. Title 13 Article 1 procedures",
  "Denver Police operations manual search",
  "C.R.C.P. Rule 121 practice standards",
  "Motion for Contempt Denver County",
  "Denver Clerk and Recorder records search",
  "Colorado Rules of Evidence 404(b)",
  "Judge Michael Vallejos criminal rulings",
  "Denver District Attorney case portal",
  "Pro-se clinic Denver City and County Building",
  "Service of Process requirements Colorado",
  "Motion to Compel Discovery C.R.C.P. 37",
  "Denver Probate Court mental health hearings"
];

interface SearchFormProps {
  params: SearchParams;
  setParams: React.Dispatch<React.SetStateAction<SearchParams>>;
  onSearch: () => void;
  isLoading: boolean;
  onClear: () => void;
  onSelectHistory: (params: SearchParams) => void;
  onSave: () => void;
  canSave: boolean;
  className?: string;
  style?: React.CSSProperties;
}

interface ScoredSuggestion {
  text: string;
  score: number;
}

export default function SearchForm({ 
  params, 
  setParams, 
  onSearch, 
  isLoading, 
  onClear, 
  onSelectHistory, 
  onSave, 
  canSave,
  className = "",
  style = {}
}: SearchFormProps): React.ReactNode {
  const [isAdvancedOpen, setIsAdvancedOpen] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [suggestions, setSuggestions] = useState<ScoredSuggestion[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(-1);
  const [isClearing, setIsClearing] = useState(false);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const suggestionRef = useRef<HTMLDivElement>(null);

  /**
   * Advanced Fuzzy Scoring Algorithm
   * Accounts for word position, prefix matching, character sequence, and gap penalties.
   */
  const calculateFuzzyScore = (input: string, target: string): number => {
    const query = input.toLowerCase().trim();
    const subject = target.toLowerCase();

    if (subject === query) return 1.0;
    if (subject.startsWith(query)) return 0.95;

    const qWords = query.split(/\s+/).filter(w => w.length > 0);
    const sWords = subject.split(/[\s,.-]+/).filter(w => w.length > 0);

    if (qWords.length === 0) return 0;

    let accumulatedScore = 0;

    qWords.forEach(qWord => {
      let maxWordScore = 0;

      sWords.forEach((sWord, sIndex) => {
        let wordScore = 0;

        if (sWord === qWord) {
          wordScore = 1.0;
        } else if (sWord.startsWith(qWord)) {
          // Weighted by how much of the word matches
          wordScore = 0.8 + (qWord.length / sWord.length) * 0.15;
        } else if (sWord.includes(qWord)) {
          wordScore = 0.6 + (qWord.length / sWord.length) * 0.1;
        } else {
          // Character sequence matching with gap penalties for typos
          let matches = 0;
          let lastFoundIdx = -1;
          let totalGaps = 0;

          for (let i = 0; i < qWord.length; i++) {
            const foundIdx = sWord.indexOf(qWord[i], lastFoundIdx + 1);
            if (foundIdx !== -1) {
              if (lastFoundIdx !== -1) {
                totalGaps += (foundIdx - lastFoundIdx - 1);
              }
              matches++;
              lastFoundIdx = foundIdx;
            }
          }

          if (matches >= Math.min(qWord.length - 1, 3)) {
            const matchRatio = matches / qWord.length;
            const gapPenalty = Math.max(0, 1 - (totalGaps / sWord.length));
            wordScore = matchRatio * gapPenalty * 0.4;
          }
        }

        // Position bias: matches earlier in the suggestion are slightly better
        const positionBonus = Math.max(0, (1 - sIndex / sWords.length) * 0.05);
        const finalWordScore = wordScore + positionBonus;

        if (finalWordScore > maxWordScore) maxWordScore = finalWordScore;
      });

      // Accumulate score weighted by query word length relative to total query
      accumulatedScore += (qWord.length / query.length) * maxWordScore;
    });

    // Final boost if the literal string is found anywhere
    if (subject.includes(query)) {
      accumulatedScore = Math.max(accumulatedScore, 0.85);
    }

    return Math.min(accumulatedScore, 0.99);
  };

  useLayoutEffect(() => {
    const textarea = textareaRef.current;
    if (textarea) {
      textarea.style.height = 'auto';
      textarea.style.height = `${Math.max(80, textarea.scrollHeight)}px`;
    }
  }, [params.query]);

  const handleInputChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const value = e.target.value;
    setParams(prev => ({ ...prev, query: value }));

    if (value.length > 1) {
      const scored = SUGGESTION_BANK.map(s => ({
        text: s,
        score: calculateFuzzyScore(value, s)
      }))
      // Lowered threshold to 0.2 to catch more typos while relying on sorting for relevance
      .filter(s => s.score > 0.22)
      .sort((a, b) => b.score - a.score)
      .slice(0, 5);

      setSuggestions(scored);
      setShowSuggestions(scored.length > 0);
      setSelectedIndex(-1);
    } else {
      setShowSuggestions(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    const hasContent = params.query.trim().length > 0;

    if (showSuggestions) {
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        setSelectedIndex(prev => (prev < suggestions.length - 1 ? prev + 1 : prev));
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        setSelectedIndex(prev => (prev > 0 ? prev - 1 : -1));
      } else if (e.key === 'Enter' && selectedIndex >= 0) {
        e.preventDefault();
        selectSuggestion(suggestions[selectedIndex].text);
      } else if (e.key === 'Escape') {
        setShowSuggestions(false);
      } else if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        if (hasContent) {
          onSearch();
        }
      }
    } else if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      if (hasContent) {
        onSearch();
      }
    }
  };

  const selectSuggestion = (text: string) => {
    setParams(prev => ({ ...prev, query: text }));
    setShowSuggestions(false);
    setSelectedIndex(-1);
    textareaRef.current?.focus();
  };

  const handleClear = () => {
    setIsClearing(true);
    setTimeout(() => {
      onClear();
      setIsClearing(false);
    }, 800);
  };

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (suggestionRef.current && !suggestionRef.current.contains(event.target as Node)) {
        setShowSuggestions(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <div className={`p-8 relative ${className}`} style={style}>
      <div className="flex flex-col gap-6">

        <div className="flex justify-between items-center text-[10px] font-mono-legal text-[#5e5239] uppercase tracking-[0.4em]">
          <div className="flex items-center gap-3">
            <span className="w-1.5 h-1.5 bg-[#a18d66] rounded-full animate-pulse shadow-[0_0_5px_#a18d66]"></span>
            Intelligence Input Console
            <span className="ml-4 opacity-40 px-2 border border-[#5e5239]/40 rounded-sm">Fuzzy_Match: ACTIVE</span>
          </div>
          <button onClick={() => setIsHistoryOpen(!isHistoryOpen)} className="hover:text-[#d1c19d] transition-colors flex items-center gap-2">
            <HistoryIcon className="w-3 h-3" />
            Archives
          </button>
        </div>

        <div className="relative group" ref={suggestionRef}>
          <textarea
            ref={textareaRef}
            value={params.query}
            onChange={handleInputChange}
            onKeyDown={handleKeyDown}
            onFocus={() => params.query.length > 1 && suggestions.length > 0 && setShowSuggestions(true)}
            placeholder="Execute Strategic Query..."
            className="w-full bg-[#050505] border border-[#5e5239]/30 p-6 font-mono-legal text-[#d1c19d] text-lg focus:outline-none focus:border-[#a18d66] transition-all min-h-[80px] placeholder:text-[#5e5239]/20 resize-none overflow-hidden shadow-[inset_0_4px_12px_rgba(0,0,0,0.8)]"
            disabled={isLoading || isClearing}
          />

          <div className="absolute top-0 right-0 p-2 pointer-events-none">
             <div className="w-2 h-2 border-t border-r border-[#a18d66]/50"></div>
          </div>
          <div className="absolute bottom-0 left-0 p-2 pointer-events-none">
             <div className="w-2 h-2 border-b border-l border-[#a18d66]/50"></div>
          </div>

          {showSuggestions && (
            <div 
              className="absolute left-0 top-full mt-2 w-full bg-[#0d0d0d] border border-[#a18d66]/40 z-50 shadow-[0_20px_50px_rgba(0,0,0,1)] animate-[fadeIn_0.15s_ease-out]"
            >
              <div className="p-2 border-b border-[#5e5239]/20 bg-[#121212]">
                <span className="text-[8px] font-black text-[#5e5239] uppercase tracking-[0.3em]">Neural intent predictions</span>
              </div>
              <div className="flex flex-col">
                {suggestions.map((s, i) => (
                  <button 
                    key={i} 
                    onClick={() => selectSuggestion(s.text)}
                    onMouseEnter={() => setSelectedIndex(i)}
                    className={`group/item text-left p-4 border-b border-[#5e5239]/10 last:border-0 transition-colors flex items-center justify-between ${selectedIndex === i ? 'bg-[#a18d66]/20' : ''}`}
                  >
                     <span className={`text-[11px] font-mono-legal transition-colors ${selectedIndex === i ? 'text-[#d1c19d]' : 'text-[#999999]'}`}>
                       <span className="text-[#a18d66] mr-3 font-bold opacity-30">></span> {s.text}
                     </span>
                     <div className="flex flex-col items-end gap-1">
                        <div className="w-12 h-1 bg-[#1a1a1a] rounded-full overflow-hidden">
                           <div className="h-full bg-[#a18d66] transition-all duration-300" style={{ width: `${s.score * 100}%` }}></div>
                        </div>
                        <span className="text-[7px] font-mono text-[#5e5239] uppercase">Confidence_{Math.round(s.score * 100)}%</span>
                     </div>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>

        <div className="flex flex-wrap items-center gap-4">
          <button 
            onClick={onSearch}
            disabled={isLoading || !params.query.trim() || isClearing}
            className="flex-grow sm:flex-grow-0 min-w-[200px] px-12 py-4 bg-[#a18d66] text-[#050505] font-black uppercase italic tracking-tighter text-lg hover:brightness-110 disabled:opacity-20 transition-all flex items-center justify-center gap-4 relative overflow-hidden group/btn"
          >
            <div className="absolute inset-0 bg-white/10 opacity-0 group-hover/btn:opacity-100 transition-opacity"></div>
            {isLoading ? (
              <>
                <SpinnerIcon className="w-5 h-5 text-[#050505]" />
                <span className="animate-pulse">Synthesizing...</span>
              </>
            ) : 'Run Analysis'}
          </button>

          <button 
            onClick={handleClear}
            disabled={isLoading || isClearing}
            className="px-8 py-4 border border-[#5e5239]/60 text-[#a18d66] font-black uppercase tracking-widest text-xs hover:bg-[#1a1a1a] hover:border-[#a18d66] transition-all flex items-center gap-3 shadow-lg"
          >
            {isClearing ? <SpinnerIcon className="w-3 h-3" /> : null}
            {isClearing ? 'Purging...' : 'Wipe Console'}
          </button>

          <button 
            onClick={() => setIsAdvancedOpen(!isAdvancedOpen)} 
            className={`flex items-center gap-3 px-6 py-4 border text-[10px] font-black uppercase tracking-widest transition-all ${isAdvancedOpen ? 'bg-[#a18d66]/10 border-[#a18d66] text-[#d1c19d]' : 'border-[#5e5239]/40 text-[#5e5239]'}`}
          >
            Tactical Params <ChevronDownIcon className={`w-3 h-3 transition-transform ${isAdvancedOpen ? 'rotate-180' : ''}`} />
          </button>
        </div>

        {isAdvancedOpen && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 pt-6 border-t border-[#5e5239]/20 animate-[fadeIn_0.3s_ease-out]">
            <div className="space-y-2">
              <label className="text-[9px] font-black text-[#5e5239] uppercase tracking-widest ml-1">Spatial Hub</label>
              <select value={params.jurisdiction} onChange={(e) => setParams({...params, jurisdiction: e.target.value as any})} className="w-full bg-[#050505] border border-[#5e5239]/50 text-[#d1c19d] text-[10px] p-3 outline-none focus:border-[#a18d66] font-mono-legal appearance-none cursor-pointer">
                <option value="all">JURISDICTION: GLOBAL</option>
                <option value="denver_district">DENVER DISTRICT</option>
                <option value="denver_county">DENVER COUNTY</option>
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-[9px] font-black text-[#5e5239] uppercase tracking-widest ml-1">Subject Profile</label>
              <select value={params.caseType} onChange={(e) => setParams({...params, caseType: e.target.value as any})} className="w-full bg-[#050505] border border-[#5e5239]/50 text-[#d1c19d] text-[10px] p-3 outline-none focus:border-[#a18d66] font-mono-legal appearance-none cursor-pointer">
                <option value="all">PROFILE: ALL</option>
                <option value="civil">CIVIL LITIGATION</option>
                <option value="criminal">CRIMINAL DEFENSE</option>
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-[9px] font-black text-[#5e5239] uppercase tracking-widest ml-1">Identifier</label>
              <input type="text" placeholder="DOCKET ID #" value={params.caseNumber || ''} onChange={(e) => setParams({...params, caseNumber: e.target.value})} className="w-full bg-[#050505] border border-[#5e5239]/50 text-[#d1c19d] text-[10px] p-3 outline-none focus:border-[#a18d66] font-mono-legal placeholder:text-[#5e5239]/30" />
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState, useCallback, useRef, useEffect, useMemo } from 'react';
import { NarrativeMapResult, NarrativeNode, NarrativeLink, TimelineEvent } from '../types';
import SpinnerIcon from './icons/SpinnerIcon';
import CloseIcon from './icons/CloseIcon';
import BrainCircuitIcon from './icons/BrainCircuitIcon';
import UserIcon from './icons/UserIcon';
import GavelIcon from './icons/GavelIcon';
import GlobeIcon from './icons/GlobeIcon';
import DocumentIcon from './icons/DocumentIcon';
import AlertIcon from './icons/AlertIcon';
import CalendarIcon from './icons/CalendarIcon';
import DownloadIcon from './icons/DownloadIcon';

interface NarrativeMapperProps {
    onClose: () => void;
    onGenerate: (base64Content: string, mimeType: string, fileName: string) => Promise<NarrativeMapResult>;
    initialData?: { b64: string, mime: string, name: string } | null;
}

const getNodeIcon = (type: string, className = "w-5 h-5") => {
    switch (type) {
        case 'person': return <UserIcon className={className} />;
        case 'location': return <GlobeIcon className={className} />;
        case 'institution': return <GavelIcon className={className} />;
        case 'event': return <CalendarIcon className={className} />;
        default: return <DocumentIcon className={className} />;
    }
};

const getNodeColor = (type: string, isBrady: boolean) => {
    if (isBrady) return 'bg-red-900 border-red-500 text-white';
    return 'bg-[#050505] border-[#b5892f] text-[#e2c07d]';
};

const EvidenceBadge: React.FC<{ tag: string }> = ({ tag }) => {
    let borderColor = "#6e501a";
    let textColor = "#a0a0a0";
    if (tag.includes("Brady")) { borderColor = "#ef4444"; textColor = "#ef4444"; }
    else if (tag.includes("613")) { borderColor = "#b5892f"; textColor = "#e2c07d"; }
    return (
        <span className="px-2 py-0.5 rounded-[2px] text-[8px] font-black uppercase border tracking-tighter shadow-sm" style={{borderColor, color: textColor, backgroundColor: 'rgba(0,0,0,0.5)'}}>
            {tag}
        </span>
    );
};

const GraphView: React.FC<{ data: NarrativeMapResult; onNodeClick: (node: NarrativeNode) => void; activeNodeId: string | null; }> = ({ data, onNodeClick, activeNodeId }) => {
    const svgRef = useRef<SVGSVGElement>(null);
    const [positions, setPositions] = useState<Record<string, { x: number, y: number }>>({});
    const [draggingId, setDraggingId] = useState<string | null>(null);

    useEffect(() => {
        const width = 800; const height = 600; const newPos: Record<string, { x: number, y: number }> = {};
        const people = data.nodes.filter(n => n.type === 'person');
        const others = data.nodes.filter(n => n.type !== 'person');
        people.forEach((node, i) => { const angle = (i / people.length) * 2 * Math.PI; newPos[node.id] = { x: 400 + Math.cos(angle) * 150, y: 300 + Math.sin(angle) * 150 }; });
        others.forEach((node, i) => { const angle = (i / others.length) * 2 * Math.PI; newPos[node.id] = { x: 400 + Math.cos(angle) * 250, y: 300 + Math.sin(angle) * 250 }; });
        setPositions(newPos);
    }, [data]);

    return (
        <div className="bg-[#050505] rounded-none overflow-hidden relative h-full w-full border border-[#6e501a]/20">
            <div className="absolute inset-0 opacity-[0.05] pointer-events-none" style={{ backgroundImage: 'radial-gradient(#b5892f 1px, transparent 1px)', backgroundSize: '40px 40px' }}></div>
            <svg ref={svgRef} width="100%" height="100%" viewBox="0 0 800 600" onMouseMove={(e) => { if (draggingId) { const r = svgRef.current!.getBoundingClientRect(); setPositions(p => ({...p, [draggingId]: { x: (e.clientX - r.left) * (800/r.width), y: (e.clientY - r.top) * (600/r.height) }})); } }} onMouseUp={() => setDraggingId(null)} className="cursor-crosshair">
                <defs>
                    <marker id="arrow" markerWidth="10" markerHeight="10" refX="28" refY="5" orient="auto"><path d="M0,0 L10,5 L0,10 Z" fill="#6e501a" /></marker>
                    <marker id="arrow-contradiction" markerWidth="10" markerHeight="10" refX="28" refY="5" orient="auto"><path d="M0,0 L10,5 L0,10 Z" fill="#ef4444" /></marker>
                </defs>
                {data.links.map((l, i) => {
                    const s = positions[l.source], e = positions[l.target]; if (!s || !e) return null;
                    const isContradiction = l.type === 'contradiction';
                    const isInferred = l.type === 'inferred';
                    return (
                        <g key={i}>
                            <line 
                                x1={s.x} y1={s.y} x2={e.x} y2={e.y} 
                                stroke={isContradiction ? '#ef4444' : (isInferred ? '#6e501a' : '#b5892f')} 
                                strokeWidth={isContradiction ? "2" : "1"} 
                                strokeDasharray={isInferred ? "5,5" : "0"}
                                opacity="0.6" 
                                markerEnd={isContradiction ? "url(#arrow-contradiction)" : "url(#arrow)"} 
                            />
                            <foreignObject x={(s.x+e.x)/2 - 50} y={(s.y+e.y)/2 - 10} width="100" height="20">
                                <div className={`text-[8px] font-black text-center uppercase tracking-tighter ${isContradiction ? 'text-red-500' : 'text-[#6e501a]'}`}>{l.label}</div>
                            </foreignObject>
                        </g>
                    );
                })}
                {data.nodes.map(n => {
                    const p = positions[n.id]; if (!p) return null;
                    const isActive = activeNodeId === n.id;
                    const color = !!n.bradyFlag ? '#ef4444' : '#b5892f';
                    return (
                        <g key={n.id} transform={`translate(${p.x}, ${p.y})`} onClick={() => onNodeClick(n)} onMouseDown={() => setDraggingId(n.id)} className="cursor-pointer">
                            <circle r="24" fill="#050505" stroke={isActive ? '#e2c07d' : color} strokeWidth={isActive ? "3" : "1"} />
                            <foreignObject x="-12" y="-12" width="24" height="24"><div className="flex justify-center" style={{color: !!n.bradyFlag ? '#ef4444' : '#b5892f'}}>{getNodeIcon(n.type, "w-6 h-6")}</div></foreignObject>
                            <text y="42" fill="#efefef" fontSize="10" fontWeight="900" textAnchor="middle" className="uppercase tracking-widest">{n.label}</text>
                            {n.bradyFlag && <circle r="6" cx="18" cy="-18" fill="#ef4444" />}
                        </g>
                    );
                })}
            </svg>
        </div>
    );
};

export default function NarrativeMapper({ onClose, onGenerate, initialData }: NarrativeMapperProps): React.ReactNode {
    const [file, setFile] = useState<File | null>(null);
    const [isLoading, setIsLoading] = useState(false);
    const [result, setResult] = useState<NarrativeMapResult | null>(null);
    const [selectedNode, setSelectedNode] = useState<NarrativeNode | null>(null);

    const handleGenerateInternal = useCallback(async (b64: string, mime: string, name: string) => {
        setIsLoading(true);
        try {
            const res = await onGenerate(b64, mime, name);
            setResult(res);
        } finally {
            setIsLoading(false);
        }
    }, [onGenerate]);

    useEffect(() => {
        if (initialData) {
            handleGenerateInternal(initialData.b64, initialData.mime, initialData.name);
        }
    }, [initialData, handleGenerateInternal]);

    const handleManualGenerate = async () => {
        if (!file) return; 
        const b64 = await new Promise<string>(r => { 
            const rd = new FileReader(); 
            rd.onload = () => r((rd.result as string).split(',')[1]); 
            rd.readAsDataURL(file); 
        });
        handleGenerateInternal(b64, file.type, file.name);
    };

    if (!result && !isLoading) {
        return (
            <div className="fixed inset-0 bg-[#050505]/95 backdrop-blur-md flex justify-center items-center z-50 p-4">
                <div className="bg-[#121212] border border-[#6e501a] p-10 max-w-xl w-full text-center relative">
                    <div className="absolute top-0 left-0 right-0 h-1 bg-[#b5892f]"></div>
                    <h2 className="text-3xl font-black text-[#efefef] tracking-tighter uppercase italic mb-6">Narrative Matrix Generator</h2>
                    <input type="file" accept="application/pdf" onChange={(e) => e.target.files && setFile(e.target.files[0])} className="hidden" id="f-mapper" />
                    <label htmlFor="f-mapper" className="block p-12 border border-dashed border-[#6e501a]/40 mb-10 cursor-pointer hover:bg-[#b5892f]/5">
