    return (
        <div className="fixed inset-0 bg-[#050505] z-50 flex flex-col animate-[fadeIn_0.3s_ease-out]">
            <div className="p-6 bg-[#121212] border-b border-[#6e501a]/30 flex justify-between items-center shadow-2xl">
