];

interface SearchFormProps {
  params: SearchParams;
  setParams: React.Dispatch<React.SetStateAction<SearchParams>>;
  onSearch: () => void;
  isLoading: boolean;
  onClear: () => void;
  onSelectHistory: (p: SearchParams) => void;
  onSave: () => void;
  canSave: boolean;
}

export default function SearchForm({ 
  params, 
  setParams, 
  onSearch, 
  isLoading, 
  onClear,
  onSelectHistory,
  onSave,
  canSave
}: SearchFormProps): React.ReactNode {
  const [isAdvancedOpen, setIsAdvancedOpen] = useState(false);
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(-1);
  const [showHistory, setShowHistory] = useState(false);
  const [historyItems, setHistoryItems] = useState<SearchParams[]>([]);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const suggestionRef = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    const textarea = textareaRef.current;
    if (textarea) {
      textarea.style.height = 'auto';
      textarea.style.height = `${Math.max(120, textarea.scrollHeight)}px`;
    }
  }, [params.query]);

  useEffect(() => {
    if (showHistory) setHistoryItems(getHistory());
  }, [showHistory]);

  const handleInputChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const value = e.target.value;
    setParams(prev => ({ ...prev, query: value }));
    if (value.length > 2) {
      const filtered = SUGGESTION_BANK.filter(s => s.toLowerCase().includes(value.toLowerCase())).slice(0, 5);
      setSuggestions(filtered);
      setShowSuggestions(filtered.length > 0);
    } else setShowSuggestions(false);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (showSuggestions) {
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        setSelectedIndex(prev => (prev < suggestions.length - 1 ? prev + 1 : prev));
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        setSelectedIndex(prev => (prev > 0 ? prev - 1 : -1));
      } else if (e.key === 'Enter' && selectedIndex >= 0) {
        e.preventDefault();
        selectSuggestion(suggestions[selectedIndex]);
      } else if (e.key === 'Escape') setShowSuggestions(false);
      else if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); onSearch(); }
    } else if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); onSearch(); }
  };

  const selectSuggestion = (text: string) => {
    setParams(prev => ({ ...prev, query: text }));
    setShowSuggestions(false);
    setSelectedIndex(-1);
    textareaRef.current?.focus();
  };

  return (
    <div className="p-8 bg-black/80 border-b border-[#00ff41]/30 relative overflow-hidden">
      <div className="absolute inset-0 opacity-[0.03] pointer-events-none font-mono text-[10px] whitespace-pre p-4">
        {Array(20).fill("A2 4F 92 11 00 FF 33 AA CC 00 21 44 82").join("\n")}
      </div>

      <div className="flex flex-col gap-6 relative z-10">
        <div className="flex justify-between items-center text-[9px] font-mono text-[#aa00ff] uppercase tracking-[0.4em]">
          <div className="flex items-center gap-3">
            <span className="w-2 h-2 bg-[#ff0033] animate-pulse"></span>
            TARGET_ACQUISITION_TERMINAL
          </div>
          <div className="flex items-center gap-6">
             <span className="text-[#00ff41]/40">NODE: DNVR_SIG_0x82</span>
             <button onClick={() => setShowHistory(!showHistory)} className="hover:text-[#00ff41] flex items-center gap-2">
               <HistoryIcon className="w-3 h-3" />
               [ARCHIVE_LOGS]
             </button>
          </div>
        </div>

        <div className="relative">
          <textarea
            ref={textareaRef}
            value={params.query}
            onChange={handleInputChange}
            onKeyDown={handleKeyDown}
            placeholder="EXECUTE_SELECTOR_INTEL..."
            className="w-full bg-black/60 border border-[#00ff41]/40 p-6 font-mono text-[#00ff41] text-2xl focus:outline-none focus:border-[#00ff41] focus:bg-[#00ff41]/5 transition-all min-h-[120px] placeholder:text-[#00ff41]/10 resize-none shadow-[inset_0_0_20px_rgba(0,255,65,0.05)]"
            disabled={isLoading}
          />
          <div className="absolute top-0 right-0 p-2"><div className="w-4 h-4 border-t border-r border-[#ff0033]"></div></div>
          <div className="absolute bottom-0 left-0 p-2"><div className="w-4 h-4 border-b border-l border-[#aa00ff]"></div></div>

          {showSuggestions && (
            <div className="absolute left-0 top-full mt-2 w-full bg-black border border-[#aa00ff] z-50 shadow-[0_10px_40px_rgba(0,0,0,0.8)]">
              <div className="p-2 border-b border-[#aa00ff]/20 bg-[#aa00ff]/10 text-[8px] font-black text-[#aa00ff] tracking-widest">[PROBABLE_MATCHES]</div>
              <div className="flex flex-col">
                {suggestions.map((s, i) => (
                  <button key={i} onClick={() => selectSuggestion(s)} className={`text-left p-4 border-b border-[#aa00ff]/10 last:border-0 transition-all text-[11px] font-mono ${selectedIndex === i ? 'bg-[#aa00ff] text-black italic' : 'text-[#aa00ff]/70'}`}>
                    >> {s}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>

        <div className="flex flex-wrap items-center gap-4">
          <button 
            onClick={onSearch}
            disabled={isLoading || !params.query.trim()}
            className="flex-grow px-12 py-5 bg-[#00ff41] text-black font-black uppercase italic tracking-tighter text-2xl hover:bg-[#aa00ff] disabled:opacity-20 transition-all flex items-center justify-center gap-4 shadow-[0_0_20px_rgba(0,255,65,0.2)]"
          >
            {isLoading ? <><SpinnerIcon className="w-6 h-6 animate-spin" /><span className="animate-pulse">PARSING_SIGINT...</span></> : '[RUN_DIAGNOSTIC]'}
          </button>

          <div className="flex gap-2">
            <button onClick={() => setIsAdvancedOpen(!isAdvancedOpen)} className={`px-6 py-5 border border-[#00ff41]/40 text-[10px] font-black uppercase tracking-widest hover:bg-[#00ff41]/10 ${isAdvancedOpen ? 'bg-[#00ff41]/20' : ''}`}>
              [FILTERS]
            </button>
            <button onClick={onSave} disabled={!canSave} className="px-6 py-5 border border-[#ff0033]/40 text-[#ff0033] text-[10px] font-black uppercase hover:bg-[#ff0033]/10 disabled:opacity-20">
              [ARCHIVE]
            </button>
            <button onClick={onClear} className="px-6 py-5 border border-white/20 text-white/40 text-[10px] font-black uppercase hover:bg-white/5">
              [PURGE]
            </button>
          </div>
        </div>

        {isAdvancedOpen && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 pt-6 border-t border-[#00ff41]/20 animate-glitch">
            <div className="space-y-2">
              <label className="text-[9px] font-black text-[#aa00ff] uppercase tracking-widest">GEO_VECTOR</label>
              <select value={params.jurisdiction} onChange={(e) => setParams({...params, jurisdiction: e.target.value as any})} className="w-full bg-black border border-[#aa00ff]/40 text-[#aa00ff] text-[10px] p-3 outline-none focus:border-[#aa00ff] appearance-none">
                <option value="all">ANY_SECTOR</option>
                <option value="denver_district">DNVR_DIST</option>
                <option value="denver_county">DNVR_CNTY</option>
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-[9px] font-black text-[#aa00ff] uppercase tracking-widest">OBJ_TYPE</label>
              <select value={params.caseType} onChange={(e) => setParams({...params, caseType: e.target.value as any})} className="w-full bg-black border border-[#aa00ff]/40 text-[#aa00ff] text-[10px] p-3 outline-none focus:border-[#aa00ff] appearance-none">
                <option value="all">ALL_OBJECTS</option>
                <option value="civil">CIVIL_FILINGS</option>
                <option value="criminal">CRIM_DOCKET</option>
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-[9px] font-black text-[#aa00ff] uppercase tracking-widest">REG_ID</label>
              <input type="text" placeholder="CASE_ID_MASK" value={params.caseNumber || ''} onChange={(e) => setParams({...params, caseNumber: e.target.value})} className="w-full bg-black border border-[#aa00ff]/40 text-[#aa00ff] text-[10px] p-3 outline-none focus:border-[#aa00ff] placeholder:text-[#aa00ff]/20" />
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

