import IdentifiedJudges from './IdentifiedJudges';
import SpinnerIcon from './icons/SpinnerIcon';
import AdversarialStrategyWidget from './AdversarialStrategyWidget';

interface ResultsDisplayProps {
  output: SearchResult | null;
  searchParams: SearchParams | null;
  isLoading: boolean;
  onQuestionClick: (q: string) => void;
  onAnalysisClick: (p: string) => void;
  onSave: (p: SearchParams, r: SearchResult) => void;
  onRemoveSave: (p: SearchParams) => void;
  isSaved: boolean;
  onJudgeClick: (n: string) => void;
}

const IntelligenceSkeleton = () => (
  <div className="flex flex-col gap-12 animate-pulse">
    <div className="tech-card p-12 border border-[#ff0033]/40">
       <div className="h-10 bg-[#ff0033]/20 w-3/4 mb-10"></div>
       <div className="space-y-6">
          <div className="h-4 bg-[#00ff41]/10 w-full"></div>
          <div className="h-4 bg-[#00ff41]/10 w-5/6"></div>
          <div className="h-4 bg-[#00ff41]/10 w-full"></div>
       </div>
    </div>
  </div>
);

export default function ResultsDisplay({ output, searchParams, isLoading, onQuestionClick, onAnalysisClick, onSave, onRemoveSave, isSaved, onJudgeClick }: ResultsDisplayProps): React.ReactNode {
  if (!output && !isLoading) return null;

  return (
    <div className="flex flex-col gap-12 mt-12 pb-20">
      {isLoading && (!output || !output.summary) ? (
        <IntelligenceSkeleton />
      ) : output ? (
        <>
          <div className="tech-card p-12 bg-black/80 border border-[#00ff41]/40 relative">
            <div className="absolute top-0 right-0 p-3 opacity-10 font-mono text-[7px] pointer-events-none select-none">
              SEC_LEV: 0x09<br/>CRYPT: RSA_2048<br/>ID: {Math.random().toString(16).substring(2, 10).toUpperCase()}
            </div>
            <div className="absolute left-0 top-0 bottom-0 w-1 bg-gradient-to-b from-[#00ff41] via-transparent to-[#00ff41]/20"></div>

            <div className="flex justify-between items-start mb-16 border-b border-[#00ff41]/20 pb-8">
              <div className="flex flex-col gap-2">
                <div className="bg-[#00ff41] text-black px-4 py-1 text-[10px] font-black uppercase tracking-[0.3em] inline-block mb-2">
                  INTERNAL_REPORT: [DE-DCO-2026]
                </div>
                <h3 className="text-sm font-black text-[#00ff41] uppercase tracking-[0.5em] glow-text glitch-text">
                  Tactical Intelligence Dossier
                </h3>
              </div>
              <button onClick={() => isSaved ? onRemoveSave(searchParams!) : onSave(searchParams!, output)} className={`p-3 border transition-all ${isSaved ? 'bg-[#00ff41] text-black border-[#00ff41]' : 'border-[#00ff41] text-[#00ff41] hover:bg-[#00ff41]/10'}`}>
                {isSaved ? <BookmarkFilledIcon className="w-6 h-6" /> : <BookmarkIcon className="w-6 h-6" />}
              </button>
            </div>

            <div className="max-w-5xl mx-auto relative z-10">
              <div className="prose prose-invert prose-2xl max-w-none text-[#00ff41] font-mono leading-relaxed 
                prose-h1:text-4xl prose-h1:text-[#ff0033] prose-h1:font-black prose-h1:italic prose-h1:mb-12
                prose-h2:text-xl prose-h2:text-[#aa00ff] prose-h2:border-l-4 prose-h2:border-[#aa00ff] prose-h2:pl-6 prose-h2:mt-16
                prose-p:mb-10 prose-p:font-light prose-p:text-lg
                prose-strong:text-black prose-strong:bg-[#00ff41] prose-strong:px-1 prose-strong:font-black
                prose-li:text-[#00ff41]/80 prose-li:mb-4">
                <ReactMarkdown remarkPlugins={[remarkGfm]}>{output.summary}</ReactMarkdown>
                {output.isSummaryStreaming && <span className="inline-block w-4 h-8 bg-[#00ff41] animate-pulse align-middle ml-2"></span>}
              </div>
            </div>
          </div>

          <AdversarialStrategyWidget strategy={output.adversarialStrategy} isLoading={output.isAdversarialLoading} />

          <div className="grid grid-cols-1 xl:grid-cols-2 gap-12">
            {output.identifiedJudges && (
              <IdentifiedJudges judges={output.identifiedJudges} isLoading={output.isIdentifiedJudgesLoading} onJudgeClick={onJudgeClick} />
            )}

            <div className="tech-card p-12 border border-[#aa00ff]/40">
              <div className="absolute top-0 right-0 bg-[#aa00ff] text-black px-2 py-0.5 text-[8px] font-black uppercase">LINK_NODES</div>
              <h4 className="text-[10px] font-black text-[#aa00ff] uppercase tracking-[0.4em] mb-10 border-b border-[#aa00ff]/20 pb-4">COLLECTED_METADATA_URIs</h4>
              <div className="flex flex-col gap-3">
                {output.sources.slice(0, 5).map((s, i) => (
                  <a key={i} href={s.uri} target="_blank" className="flex items-center justify-between p-4 bg-black/40 border border-[#aa00ff]/30 hover:border-[#aa00ff] hover:bg-[#aa00ff]/5 transition-all group">
                    <div className="flex items-center gap-4 truncate">
                      <GlobeIcon className="w-4 h-4 text-[#aa00ff]" />
                      <span className="truncate text-[11px] font-mono text-[#aa00ff] font-bold">{s.title}</span>
                    </div>
                    <span className="text-[9px] text-[#aa00ff] opacity-40 group-hover:opacity-100 transition-opacity ml-4">FETCH_0x{i}</span>
                  </a>
                ))}
              </div>
            </div>
          </div>

          {output.timelineEvents && (
            <div className="tech-card p-12 border border-[#00ff41]/40">
              <TimelineChart events={output.timelineEvents} isLoading={output.isTimelineLoading} />
            </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
            <FollowUpQuestions questions={output.followUpQuestions || []} onQuestionClick={onQuestionClick} />
            <RelatedQueries queries={output.relatedQueries || []} onQueryClick={onQuestionClick} />
          </div>
        </>
      ) : null}
    </div>
  );
}

import React from 'react';
import { type AdversarialStrategy } from '../types';
import GavelIcon from './icons/GavelIcon';
import AlertIcon from './icons/AlertIcon';
import SparklesIcon from './icons/SparklesIcon';
import SpinnerIcon from './icons/SpinnerIcon';
import BrainCircuitIcon from './icons/BrainCircuitIcon';

interface AdversarialStrategyWidgetProps {
  strategy?: AdversarialStrategy;
  isLoading?: boolean;
}

export default function AdversarialStrategyWidget({ strategy, isLoading }: AdversarialStrategyWidgetProps): React.ReactNode {
  if (isLoading) {
    return (
      <div className="tech-card p-20 bg-black border-2 border-[#ff0033] flex flex-col items-center justify-center gap-8 text-[#ff0033]">
        <SpinnerIcon className="w-16 h-16 animate-spin opacity-50" />
        <span className="text-[14px] font-black uppercase tracking-[1em] animate-pulse">WAR_ROOM_SIM_ACTIVE...</span>
      </div>
    );
  }

  if (!strategy || (!strategy.prosecutorMoves.length && !strategy.defenseCounters.length)) return null;

  return (
    <div className="relative group animate-glitch">
      <div className="tech-card p-12 bg-black border border-[#ff0033]/60 shadow-[0_0_80px_rgba(255,0,51,0.15)] overflow-hidden">
        <div className="absolute top-0 left-0 bg-[#ff0033] text-black px-4 py-1 text-[10px] font-black uppercase z-20">
          THREAT_ASSESSMENT_v9.X
        </div>
        <div className="absolute bottom-0 right-0 p-4 opacity-5 pointer-events-none select-none">
          <BrainCircuitIcon className="w-64 h-64 text-[#ff0033]" />
        </div>

        <div className="flex flex-col lg:flex-row justify-between items-start mb-16 border-b border-[#ff0033]/20 pb-12 gap-12 relative z-10">
          <div className="flex items-center gap-10">
            <div className="p-5 bg-[#ff0033] text-black shadow-[0_0_20px_#ff0033]">
              <BrainCircuitIcon className="w-10 h-10" />
            </div>
            <div>
              <h3 className="text-5xl font-black text-white tracking-tighter uppercase italic glow-text">PREDICTIVE_WAR_ROOM</h3>
              <div className="flex items-center gap-4 mt-3">
                 <span className="w-2 h-2 bg-[#ff0033] animate-ping"></span>
                 <p className="text-[12px] text-[#ff0033] font-black uppercase tracking-[0.5em]">Tactical_Simulation_Live</p>
              </div>
            </div>
          </div>
          <div className="flex flex-col lg:items-end gap-3">
             <div className="bg-[#ff0033] text-black px-10 py-4 font-black text-2xl uppercase tracking-tighter italic">
               THREAT: CRITICAL
             </div>
             <span className="text-[9px] text-[#ff0033]/60 font-mono">SECTOR_ID: DNVR_COURT_0x11</span>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-16 relative z-10">
          <div className="space-y-10 relative">
            <h4 className="flex items-center text-[11px] font-black text-[#ff0033] uppercase tracking-widest gap-4 pb-4 border-b border-[#ff0033]/20">
              <GavelIcon className="w-4 h-4" /> ADVERSARIAL_INTEL
            </h4>
            <ul className="space-y-8">
              {strategy.prosecutorMoves.map((move, i) => (
                <li key={i} className="text-xl text-[#ff0033]/90 border-l-4 border-[#ff0033] pl-8 py-2 leading-tight font-black italic">
                  <span className="text-[10px] opacity-40 mr-4 font-mono">NODE_0x{i}</span> {move}
                </li>
              ))}
            </ul>
          </div>

          <div className="space-y-10 lg:-mt-12">
            <div className="tech-card p-10 bg-[#00ff41]/5 border-2 border-[#00ff41] shadow-[0_0_40px_rgba(0,255,65,0.1)] relative">
                <div className="absolute top-0 right-0 px-3 py-1 bg-[#00ff41] text-black text-[9px] font-black">EXPLOIT_VECTOR</div>
                <h4 className="flex items-center text-[11px] font-black text-[#00ff41] uppercase tracking-widest gap-4 pb-6 border-b border-[#00ff41]/30 mb-10">
                  <SparklesIcon className="w-5 h-5 animate-pulse" /> SYSTEM_COUNTERMEASURES
                </h4>
                <ul className="space-y-12">
                {strategy.defenseCounters.map((counter, i) => (
                    <li key={i} className="text-2xl text-white pl-8 border-l-4 border-[#00ff41] py-1 leading-[1.1] font-black uppercase italic tracking-tighter">
                      {counter}
                    </li>
                ))}
                </ul>
            </div>
          </div>

          <div className="space-y-10">
            <h4 className="flex items-center text-[11px] font-black text-[#aa00ff] uppercase tracking-widest gap-4 pb-4 border-b border-[#aa00ff]/20">
              <AlertIcon className="w-4 h-4" /> ANOMALY_DETECTION
            </h4>
            <ul className="space-y-8">
              {strategy.hiddenRisks.map((risk, i) => (
                <li key={i} className="text-lg text-[#aa00ff] border-l-4 border-[#aa00ff] pl-8 py-2 leading-relaxed font-mono font-bold bg-[#aa00ff]/5">
                   <span className="text-[#aa00ff]/40 text-[10px] block mb-2">RISK_SIG: {Math.random().toString(16).substring(2,6)}</span>
                   {risk}
                </li>
              ))}
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
}

import React from 'react';
import { JudgeSummary } from '../types';
import GavelIcon from './icons/GavelIcon';

interface IdentifiedJudgesProps {
  judges: JudgeSummary[];
  isLoading: boolean;
  onJudgeClick: (judgeName: string) => void;
}

export default function IdentifiedJudges({ judges, isLoading, onJudgeClick }: IdentifiedJudgesProps): React.ReactNode {
  if (isLoading) return null;
  if (!judges || judges.length === 0) return null;

  return (
    <div className="tech-card p-12 border border-[#ff0033]/40">
      <div className="absolute top-0 right-0 bg-[#ff0033] text-black px-2 py-0.5 text-[8px] font-black uppercase tracking-widest">TARGET_PROFILE_IDs</div>
      <h4 className="text-[10px] font-black text-[#ff0033] uppercase tracking-[0.4em] mb-10 flex items-center gap-4">
        <GavelIcon className="w-4 h-4" />
        JUDICIAL_INTERCEPT_NODES
      </h4>
      <div className="flex flex-wrap gap-4">
        {judges.map((judge, index) => (
          <button
            key={index}
            onClick={() => onJudgeClick(judge.name)}
            className="group flex items-center px-6 py-4 bg-black border border-[#ff0033] text-[#ff0033] text-[11px] font-black uppercase tracking-widest hover:bg-[#ff0033] hover:text-black transition-all"
          >
            <span className="mr-4 opacity-30 font-mono">0x{index}</span>
            {judge.name}
          </button>
        ))}
      </div>
    </div>
  );
}

import React from 'react';
import { TimelineEvent } from '../types';
import CalendarIcon from './icons/CalendarIcon'; 

interface TimelineChartProps {
    events: TimelineEvent[];
    isLoading: boolean;
}

export default function TimelineChart({ events, isLoading }: TimelineChartProps): React.ReactNode {
    if (isLoading) return null;
    if (!events || events.length === 0) return null;

    const sortedEvents = [...events].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    return (
        <div className="relative">
            <div className="flex items-center gap-4 mb-12">
                <div className="p-3 bg-[#00ff41] text-black">
                    <CalendarIcon className="w-6 h-6" />
                </div>
                <div>
                    <h4 className="text-xl font-black text-[#00ff41] uppercase italic tracking-tighter">Tactical Progression Map</h4>
                    <p className="text-[9px] text-[#00ff41]/50 font-black uppercase tracking-[0.4em] mt-1">SIGINT Chronological Vectors</p>
                </div>
            </div>

            <div className="relative">
                <div className="absolute left-6 top-0 bottom-0 w-px bg-[#00ff41]/20"></div>
                <div className="space-y-12">
                    {sortedEvents.map((event, index) => (
                        <div key={index} className="flex gap-10 group animate-[fadeIn_0.5s_ease-out]">
                            <div className="flex-shrink-0 flex flex-col items-center">
                                <div className="w-12 h-12 flex items-center justify-center bg-black border border-[#00ff41] text-[#00ff41] z-10 shadow-[0_0_10px_rgba(0,255,65,0.2)]">
                                    <span className="text-[10px] font-black">{index + 1}</span>
                                </div>
                            </div>
                            <div className="flex-grow">
                                <div className="flex items-center gap-4 mb-3">
                                    <span className="font-mono font-black text-xs text-[#aa00ff] bg-black border border-[#aa00ff]/20 px-3 py-1">
                                        {event.date}
                                    </span>
                                    <span className="text-[9px] font-black uppercase tracking-widest text-[#00ff41]/50">
                                        {event.type}
                                    </span>
                                </div>
                                <div className="p-6 bg-black/40 border border-[#00ff41]/10 hover:border-[#00ff41]/40 transition-all border-l-4 border-l-[#00ff41]">
                                    <p className="text-lg text-[#00ff41]/80 leading-relaxed font-light italic">
                                        "{event.description}"
                                    </p>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
}
